KB.lade("ostafrika",[{"id":"ostafrika-doro-wat","name":"Doro Wat mit Injera","originalname":"ዶሮ ወጥ (Doro Wot)","kueche":"ostafrika","region":"Äthiopien","beliebtheit":86,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Hühnerragout in tiefroter Berbere-Zwiebelsauce mit Kräuterbutter und hartgekochten Eiern, serviert auf säuerlichem Fladenbrot.","hintergrund":"Doro Wat ist das Festgericht Äthiopiens – zu Weihnachten, Ostern und Hochzeiten gehört es auf den Tisch. Es beginnt mit einer erstaunlichen Menge an Zwiebeln, die ohne Fett lange „trocken“ gegart werden, bis sie zerfallen und die Basis der Sauce bilden. Dazu kommen Berbere (Chili-Gewürzmischung), Niter Kibbeh (gewürzte Butter) und hartgekochte Eier. Man isst es mit Injera, dem säuerlichen Sauerteig-Fladen, mit der rechten Hand. Marcus Samuelsson, in Äthiopien geboren und in Schweden aufgewachsen, hat Doro Wat zu einer Pasta-Variation weiterentwickelt.","portionen":6,"zeit":{"vorbereitung":30,"garen":120,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Hauptzutaten","liste":[{"menge":1.5,"einheit":"kg","name":"Hähnchenschenkel und -keulen, bone-in","hinweis":"Haut abziehen"},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"Saft"},{"menge":1.5,"einheit":"kg","name":"rote Zwiebeln","hinweis":"sehr fein gehackt oder gerieben"},{"menge":6,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"Stück","name":"Ingwer, daumengroß","hinweis":"fein gerieben"},{"menge":100,"einheit":"g","name":"Niter Kibbeh oder Ghee","hinweis":"Ersatz: Ghee mit Kardamom, Kreuzkümmel, Bockshornklee"},{"menge":4,"einheit":"EL","name":"Berbere-Gewürzmischung","hinweis":"Afro-/Gewürzladen oder online; Menge nach Schärfe"},{"menge":2,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":250,"einheit":"ml","name":"Wasser oder Hühnerbrühe","hinweis":""},{"menge":6,"einheit":"Stück","name":"Eier","hinweis":"hartgekocht, geschält"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Servieren","liste":[{"menge":6,"einheit":"Stück","name":"Injera","hinweis":"aus dem Afro-Laden; Ersatz: dünne Sauerteig-Pfannkuchen"}]}],"ausruestung":["schwerer Schmortopf mit Deckel","Holzlöffel","Reibe für die Zwiebeln"],"schritte":[{"titel":"Mise en place und Hähnchen beizen","aktion":"marinieren","text":"Ziehe die Haut vom Hähnchen ab und ritze das Fleisch mit einem scharfen Messer 2–3 Mal tief ein. Reibe es mit Zitronensaft und 1 TL Salz ein und lasse es mindestens 20 Minuten stehen. Die Säure macht das Fleisch zarter und nimmt Fremdgerüche. Hacke inzwischen alle Zwiebeln sehr fein oder reibe sie grob, Knoblauch und Ingwer hackst du ebenfalls fein. Koche die Eier 10 Minuten hart, schrecke sie ab und schäle sie.","dauer":25,"tipp":""},{"titel":"Zwiebeln trocken garen","aktion":"schmoren","text":"Gib die Zwiebeln ohne Fett in den schweren Topf und erhitze sie bei mittlerer Hitze unter häufigem Rühren 25–30 Minuten, bis sie ihr Wasser abgegeben haben, zusammenfallen und goldfarben werden. Dieser Schritt ist die Basis der gesamten Sauce: Je gründlicher die Zwiebeln garen, desto dicker und süßer wird sie später. Sie dürfen nicht anbrennen; spritzt es, reduziere die Hitze.","dauer":30,"tipp":"Nimm einen breiten, schweren Topf – dann verdampft die Flüssigkeit gleichmäßig."},{"titel":"Butter und Gewürzbasis","aktion":"anbraten","text":"Gib die Hälfte der Niter Kibbeh sowie Knoblauch und Ingwer zu den Zwiebeln und schwitze 5 Minuten, bis es intensiv duftet. Rühre Tomatenmark und Berbere ein und röste die Paste 5–8 Minuten bei niedriger Hitze unter ständigem Rühren, bis die Farbe von Hellrot zu tiefem Rostrot wechselt und das Fett am Rand rot schimmert. Der Berbere röstet dabei an und verliert Bitterkeit. Gieße bei Bedarf einen Schuss Wasser nach, wenn sie anzubrennen droht.","dauer":15,"tipp":""},{"titel":"Hähnchen einlegen","aktion":"schmoren","text":"Lege die Hähnchenteile in die Sauce und wende sie, bis alle Stücke rot überzogen sind. Gieße 250 ml Wasser oder Brühe an, bringe es zum Köcheln und setze den Deckel schräg auf. Schmore bei niedriger Hitze 40 Minuten. Rühre alle 10 Minuten und drehe die Stücke, damit sie gleichmäßig Farbe annehmen. Achte darauf, dass die Hähnchenstücke nicht trocken liegen: lieber einen Schuss Wasser zu viel als zu wenig, er verkocht ohnehin.","dauer":40,"tipp":""},{"titel":"Eier einlegen","aktion":"koecheln","text":"Steche die gekochten Eier mehrfach mit einer Gabel oder einem Messer ein, damit die Sauce eindringt und sie marmoriert aussehen. Lege sie in die Sauce, gib die restliche Niter Kibbeh dazu und koche weitere 20 Minuten ohne Deckel, bis die Sauce dick und glänzend ist und das Hähnchen sich vom Knochen löst. Die Sauce sollte löffelfest sein, nicht suppig.","dauer":20,"tipp":""},{"titel":"Abschmecken","aktion":"abschmecken","text":"Probiere die Sauce: Sie soll warm-scharf, leicht süß von den Zwiebeln, würzig-buttrig und salzig sein. Fehlt Tiefe, hilft eine Prise Salz oder etwas mehr Berbere; ist sie zu scharf, hilft ein Löffel Butter. Prüfe, ob das Fleisch mit leichtem Druck vom Knochen fällt (Kerntemperatur über 85 °C). Erst jetzt wird endgültig nachgesalzen, weil die eingekochte Sauce deutlich salziger wirkt als zu Beginn der Garzeit.","dauer":5,"tipp":""},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lasse das Gericht zugedeckt 10 Minuten ruhen. Die Sauce wird dadurch noch dicker, und Fleisch und Eier saugen Aromen auf. Wie bei vielen Eintöpfen schmeckt Doro Wat am nächsten Tag noch besser. Lege in dieser Zeit die Injera bereit und wärme sie kurz in einer trockenen Pfanne oder in Alufolie im Ofen bei 100 °C an, damit sie weich und geschmeidig sind. Decke die Fladen mit einem feuchten Tuch ab, damit sie nicht austrocknen.","dauer":10,"tipp":""},{"titel":"Anrichten auf Injera","aktion":"anrichten","text":"Lege ein Injera auf einen großen Teller, verteile die Sauce samt Fleisch und Eiern in der Mitte und serviere weitere Injera aufgerollt dazu. Die Sauce wird mit einem Stück Injera aufgenommen, ohne Besteck, mit der rechten Hand. Gemeinsames Essen aus einer Platte ist Teil des Rituals (Gursha: man füttert sich gegenseitig).","dauer":0,"tipp":""}],"profitipps":["Zwiebeln ohne Fett garen – die Menge ist enorm und der wichtigste Geschmacksträger.","Berbere bei niedriger Hitze anrösten, sonst wird die Sauce bitter.","Nimm echte Niter Kibbeh für Authentizität; Ghee mit Gewürzen funktioniert als Ersatz.","Eier einstechen, damit sie Farbe und Aroma annehmen.","Mit Geduld kochen: 2 Stunden Gesamtzeit sind normal."],"varianten":["Siga Wat mit Rindfleisch","Misir Wot mit roten Linsen (vegan in der Fastenzeit)","Samuelssons Doro-Wat-Pasta"],"beilagen":["Injera","Ayib (frischer Käse)","Gomen (Collard Greens)"],"getraenk":"Tej (Honigwein) oder ein kräftiger Rotwein mit weicher Struktur","koeche":[{"name":"Marcus Samuelsson","bezug":"Der in Äthiopien geborene, in Schweden aufgewachsene Sternekoch hat mit seiner Doro-Wat-Pasta einen vielbeachteten Brückenschlag zwischen äthiopischer Küche und italienischem Klassiker gemacht.","quelle":"https://www.celebritycruises.com/blog/marcus-samuelsson-doro-wat-pasta-recipe"}],"quellen":[{"titel":"Celebrity Cruises – Marcus Samuelsson Doro Wat Pasta","url":"https://www.celebritycruises.com/blog/marcus-samuelsson-doro-wat-pasta-recipe"},{"titel":"TasteAtlas – Best Rated Dishes in Africa","url":"https://tasteatlas.com/best-rated-dishes-in-africa"},{"titel":"OkayAfrica – 50 of the Best African Foods","url":"https://okayafrica.com/african-countries-best-food-dishes-cuisine"}],"bild":"eintopf","farben":["#a8321a","#e2692f","#f2d19a"],"schlagworte":["Äthiopien","Festessen","Berbere","Injera"],"vegetarisch_moeglich":false},{"id":"ostafrika-injera-selbst-backen","name":"Injera selbst backen (Teff-Sauerteigfladen)","originalname":"እንጀራ (Ǝnǧära)","kueche":"ostafrika","region":"Äthiopien / Eritrea","beliebtheit":84,"hauptkategorie":"vegan","fleischsorte":"","gang":"brot","kurz":"Das säuerliche, schwammige Fladenbrot aus Teff ist Teller, Besteck und Beilage in einem – und gelingt zu Hause mit etwas Geduld und einer beschichteten Pfanne.","hintergrund":"Injera ist das Grundnahrungsmittel Äthiopiens und Eritreas: ein Fladen aus fermentiertem Teffmehl, schwammig, leicht säuerlich und auf einer Seite von kleinen „Augen“ übersät. Traditionell wird der dünne Teig auf einer großen Tonplatte (Mitad) gebacken, die über dem Feuer liegt. Auf einem großen Injera werden Wot, Tibs und Gemüse angerichtet, mit weiteren gefalteten Injera greift man die Bissen vom gemeinsamen Teller. Teff ist ein winziges, glutenfreies Getreide, das im Hochland seit Jahrtausenden angebaut wird. Die Fermentation dauert je nach Haus zwischen einem und mehreren Tagen und gibt dem Brot seinen typischen Geschmack.","portionen":4,"zeit":{"vorbereitung":30,"garen":45,"ruhen":4320},"schwierigkeit":3,"zutaten":[{"gruppe":"Für den Teig (ergibt etwa 8 Injera à 26 cm)","liste":[{"menge":300,"einheit":"g","name":"Teffmehl","hinweis":"hell (Ivory) für mildes, braun (Brown) für kräftigeres Aroma; Bioladen, Reformhaus, Online"},{"menge":450,"einheit":"ml","name":"lauwarmes Wasser","hinweis":"für den Ansatz, 25–28 °C; zum Einstellen später ca. 150–250 ml weiteres Wasser"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":"erst kurz vor dem Backen einrühren"}]},{"gruppe":"Optional: Absit (macht die Fladen weicher)","liste":[{"menge":100,"einheit":"ml","name":"reifer Teig","hinweis":"aus dem fermentierten Ansatz"},{"menge":200,"einheit":"ml","name":"Wasser"}]}],"ausruestung":["Glas- oder Keramikschüssel (2–3 l)","saubere Tücher zum Abdecken","große beschichtete Pfanne (26–30 cm) mit Deckel","Schöpfkelle (ca. 120 ml)","Küchenthermometer (optional)"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege 300 g Teffmehl ab und stelle eine saubere Glas- oder Keramikschüssel von 2–3 Litern Fassungsvermögen bereit. Metallschüsseln aus Aluminium solltest du meiden, weil die Säure des Sauerteigs sie angreift. Lass abgekochtes Wasser auf etwa 27 °C abkühlen oder nimm abgestandenes Leitungswasser. Suche außerdem einen Platz mit konstanten 24–26 °C, etwa neben der Heizung oder im Backofen mit angeschalteter Lampe. Zu kühl heißt langsame Gärung, zu warm macht den Ansatz bitter.","dauer":0,"tipp":"Alle Gefäße vorher heiß ausspülen – saubere Geräte verhindern, dass sich Schimmel statt guter Milchsäurebakterien ansiedelt."},{"titel":"Ansatz anrühren","aktion":"mischen","text":"Gib das Teffmehl in die Schüssel und rühre nach und nach die 450 ml lauwarmes Wasser ein. Rühre mit einem Schneebesen, bis keine Klümpchen mehr zu sehen sind; die Masse sollte die Konsistenz von dickem Pfannkuchenteig haben und eine gleichmäßig graubraune Farbe zeigen. Decke die Schüssel nur locker mit einem Tuch ab, damit Gärgase entweichen können und trotzdem keine Fliegen hineinkommen. Beschrifte dir den Startzeitpunkt, denn nun beginnt die eigentliche Arbeit: das Warten.","dauer":0,"tipp":"Wildhefen und Milchsäurebakterien am Mehl sorgen für die Gärung – daher Teffmehl möglichst frisch und aus Vollkorn kaufen."},{"titel":"Fermentieren (2–3 Tage)","aktion":"gehen","text":"Lass den Ansatz bei etwa 24–26 °C stehen und rühre ihn einmal am Tag kurz durch. Schon nach 24 Stunden siehst du kleine Bläschen an der Oberfläche, und der Geruch wird säuerlich-hefig wie ein junger Sauerteig. Nach 48 bis 72 Stunden ist die Masse deutlich aufgegangen, schäumt und hat sich in eine Teigschicht unten und eine Wasserschicht oben getrennt. Je länger die Gärung, desto saurer das Injera; zwei Tage ergeben ein mildes, drei Tage ein klassisch kräftiges Aroma.","dauer":2880,"tipp":"Wer es sehr mild mag, backt schon nach 24 Stunden – dann bleiben die Fladen aber flacher und haben weniger Augen."},{"titel":"Reife prüfen und Teig einstellen","aktion":"mischen","text":"Gieße die graue Flüssigkeit an der Oberfläche vorsichtig ab, sie heißt Ersho und kann als Starter für den nächsten Ansatz aufgehoben werden. Rühre den Teig kräftig um und rieche daran: Er soll angenehm säuerlich nach Bier und Joghurt duften. Riecht er nach Nagellackentferner oder siehst du Schimmelflecken, musst du ihn wegwerfen. Rühre jetzt so viel Wasser ein, dass der Teig wie dünne Sahne vom Löffel läuft; ein Löffelrücken sollte nur einen hauchdünnen Film behalten.","dauer":0,"tipp":"Ein guter Test: Lässt du einen Tropfen in die heiße Pfanne laufen, soll er sich sofort zu einem dünnen, flachen Kreis verteilen."},{"titel":"Absit kochen (optional, für weiche Fladen)","aktion":"kochen","text":"Verrühre 100 ml reifen Teig mit 200 ml Wasser in einem kleinen Topf und erhitze die Mischung unter ständigem Rühren, bis sie dick wird und blubbert wie ein Pudding. Das dauert etwa 3–5 Minuten bei mittlerer Hitze. Der Kleister, in Äthiopien Absit genannt, wird komplett abgekühlt, bis er unter 40 °C hat, und dann zurück in den Teig gerührt. Lass den Teig danach noch eine bis zwei Stunden ruhen, bis er wieder leicht Blasen wirft. Die vorgequollene Stärke sorgt für die geschmeidige, nicht brüchige Krume.","dauer":10,"tipp":"Rühre den heißen Absit nie direkt in den Teig – er würde die Gärkulturen abtöten."},{"titel":"Pfanne vorheizen und Salz einrühren","aktion":"vorbereiten","text":"Rühre nun 1 Teelöffel Salz in den Teig, kurz vorher würde es die Gärung bremsen. Erhitze die große beschichtete Pfanne ohne Fett auf mittlerer bis hoher Stufe, bis ein Tropfen Wasser sofort tanzt und verzischt; die Oberfläche sollte etwa 180–200 °C haben. Wische die Pfanne mit einem leicht geölten Küchenpapier kurz aus und lege den Deckel in Griffweite bereit. Ist die Pfanne zu kalt, klebt der Teig an und bildet keine Augen; ist sie zu heiß, wird die Unterseite braun und spröde.","dauer":0,"tipp":""},{"titel":"Backen: ein Fladen nach dem anderen","aktion":"braten","text":"Schöpfe etwa 120 ml Teig auf die Kelle und gieße ihn in einer Spirale vom Pfannenrand zur Mitte hin ein, dann kippe die Pfanne leicht, damit der Boden vollständig bedeckt ist. Innerhalb von Sekunden bilden sich winzige Löcher – die „Augen“ – und der Rand beginnt sich zu lösen. Setze nun den Deckel auf und backe 2–3 Minuten, bis die Oberfläche matt, trocken und leicht porös aussieht und der Fladen sich am Rand wellt. Wende Injera niemals, denn die Oberseite gart im Dampf durch.","dauer":3,"tipp":"Wird die Oberfläche noch glänzend nass, braucht der Fladen länger – nicht zu früh vom Herd nehmen, sonst bleibt er klebrig."},{"titel":"Abkühlen lassen","aktion":"kuehlen","text":"Löse den Fladen mit einem breiten Spatel und lege ihn mit der Augenseite nach oben auf ein sauberes Tuch oder ein Kuchengitter. Stapele die Fladen erst, wenn sie vollständig ausgekühlt sind, sonst kleben sie durch den Dampf aneinander. Backe die restlichen Fladen nach, jeweils mit einem kurzen Wischer Öl in der Pfanne, falls der Teig zu haften beginnt. Gut abgekühlte Injera lassen sich in einem Tuch oder einem verschlossenen Beutel zwei Tage frisch halten.","dauer":15,"tipp":""},{"titel":"Anrichten und Essen","aktion":"anrichten","text":"Lege ein großes Injera als Unterlage auf einen runden Teller oder ein Brett und verteile darauf die Wot-Saucen, Gemüse und Fleisch in kleinen Häufchen. Rolle oder falte weitere Injera und stelle sie am Rand bereit. Gegessen wird nur mit der rechten Hand: Du reißt ein Stück ab, greifst damit einen Bissen und führst ihn zum Mund. Zum Schluss isst man das mit Sauce vollgesogene Injera vom Teller – es ist der beste Bissen des Abends.","dauer":0,"tipp":""}],"profitipps":["Reinen Teff gibt es oft nur in Bioläden; für den Einstieg kannst du 50 % Teff mit Buchweizen- oder Weizenmehl mischen, schmeckt aber weniger authentisch.","Ersho (die abgegossene Flüssigkeit) als Starter für den nächsten Ansatz nutzen – der Teig fermentiert dann schneller und zuverlässiger.","Die Pfanne darf nicht eingefettet sein, nur hauchdünn ausgewischt, sonst bilden sich keine Augen.","Zu dicker Teig führt zu festen, brotigen Fladen; lieber etwas dünner einstellen und die Menge pro Fladen reduzieren.","Gelingt der erste Fladen nicht, ist das normal – er dient zum Einstellen von Hitze und Teigkonsistenz."],"varianten":["Kürzere Variante: Teff mit Wasser und etwas Backpulver und Sprudelwasser, wird am selben Tag gebacken (geht schnell, schmeckt milder)","Eritreisches Taita, fast identisch, aber oft dicker und kleiner","Injera aus Teff-Gerste- oder Hirse-Mischung, wie sie in ländlichen Regionen verwendet wird"],"beilagen":["Doro Wat","Misir Wot","Tibs","Shiro","Gomen (Kohlgemüse)"],"getraenk":"Tej (äthiopischer Honigwein), Bier oder Buna (Kaffeezeremonie) nach dem Essen","koeche":[{"name":"Yohanis Gebreyesus","bezug":"Der in Äthiopien geborene, in Lyon ausgebildete Koch beschreibt in seinem Buch zwei Injera-Versionen: eine über eine Woche fermentierte und eine schnelle, die schon nach einem Tag fertig ist.","quelle":"https://www.publishersweekly.com/9781623719630"}],"quellen":[{"titel":"Publishers Weekly – Rezension zu „Ethiopia: Recipes and Traditions from the Horn of Africa“ (Yohanis Gebreyesus)","url":"https://www.publishersweekly.com/9781623719630"},{"titel":"Britannica – Injera","url":"https://www.britannica.com/topic/injera"}],"bild":"brot","farben":["#c9a97a","#8a6a3e","#f1e2c5"],"schlagworte":["Teff","glutenfrei","Sauerteig","Äthiopien","Eritrea","Fladenbrot"],"vegetarisch_moeglich":true,"themen":[]},{"id":"ostafrika-pilau-sansibar","name":"Sansibar-Pilau mit Rindfleisch","originalname":"Pilau","kueche":"ostafrika","region":"Sansibar / Tansania / Küste Kenias","beliebtheit":80,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Duftender Gewürzreis mit zartem Rindfleisch, tief gebräunten Zwiebeln und Kokosmilch – das Festessen der Swahili-Küste.","hintergrund":"Pilau ist die Swahili-Variante des persisch-indischen Pulao, die über den Indischen Ozean an die ostafrikanische Küste kam. Auf Sansibar und in Tansania gehört das Gericht zu Festen, Hochzeiten und Sonntagen; typische Gewürze sind Kreuzkümmel, Kardamom, Nelken, Zimt und Pfeffer. Charakteristisch sind die lang und dunkel gebratenen Zwiebeln, die dem Reis seine braune Farbe und eine feine Süße geben. Das Fleisch gart zunächst in einer Brühe, die später als Kochflüssigkeit für den Reis dient, so zieht der volle Fleischgeschmack in jedes Korn. Dazu isst man frischen Tomaten-Zwiebel-Salat (Kachumbari).","portionen":4,"zeit":{"vorbereitung":30,"garen":110,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch und Brühe","liste":[{"menge":600,"einheit":"g","name":"Rindfleisch aus der Schulter oder Wade","hinweis":"in 3 cm große Würfel geschnitten"},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"halbiert, für die Brühe"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"angedrückt"},{"menge":1,"einheit":"l","name":"Wasser"},{"menge":2,"einheit":"Stück","name":"Lorbeerblätter"},{"menge":1,"einheit":"TL","name":"Salz"}]},{"gruppe":"Pilau-Masala (selbst gemahlen)","liste":[{"menge":2,"einheit":"TL","name":"Kreuzkümmelsamen"},{"menge":1,"einheit":"TL","name":"Kardamomsamen","hinweis":"aus ca. 10 Kapseln"},{"menge":6,"einheit":"Stück","name":"Gewürznelken"},{"menge":1,"einheit":"TL","name":"schwarze Pfefferkörner"},{"menge":1,"einheit":"Stück","name":"Zimtstange","hinweis":"ca. 5 cm"}]},{"gruppe":"Reis","liste":[{"menge":400,"einheit":"g","name":"Basmatireis","hinweis":"gründlich gewaschen, 20 Minuten eingeweicht"},{"menge":3,"einheit":"Stück","name":"große Zwiebeln","hinweis":"in halbe Ringe geschnitten"},{"menge":5,"einheit":"EL","name":"Pflanzenöl"},{"menge":6,"einheit":"Zehe","name":"Knoblauch"},{"menge":1,"einheit":"Stück","name":"Ingwerstück","hinweis":"daumengroß, fein gerieben"},{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":"gewürfelt"},{"menge":3,"einheit":"Stück","name":"mittelgroße Kartoffeln","hinweis":"in 2 cm Würfeln, optional"},{"menge":100,"einheit":"ml","name":"Kokosmilch"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Kachumbari (Frischsalat)","liste":[{"menge":2,"einheit":"Stück","name":"Tomaten"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel"},{"menge":1,"einheit":"Stück","name":"grüne Chili","hinweis":"nach Schärfe"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":"Saft"},{"menge":1,"einheit":"Handvoll","name":"Koriandergrün"}]}],"ausruestung":["großer Topf mit schwerem Boden und dicht schließendem Deckel","Gewürzmühle oder Mörser","Sieb","sauberes Küchentuch"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide das Rindfleisch in etwa 3 cm große Würfel und tupfe es trocken. Schäle die Zwiebeln und schneide sie in halbe Ringe von etwa 3 mm Dicke, schneide die Kartoffeln in 2 cm große Würfel und lege sie in Wasser. Wasche den Basmatireis in mehreren Wassern, bis das Wasser fast klar ist, und lasse ihn 20 Minuten in kaltem Wasser quellen. Presse den Knoblauch und reibe den Ingwer fein. So kannst du später ohne Unterbrechung arbeiten, denn die Zwiebeln brauchen deine volle Aufmerksamkeit.","dauer":0,"tipp":""},{"titel":"Pilau-Masala rösten und mahlen","aktion":"vorbereiten","text":"Röste Kreuzkümmel, Kardamomsamen, Nelken, Pfefferkörner und die in Stücke gebrochene Zimtstange in einer trockenen Pfanne bei mittlerer Hitze etwa 1–2 Minuten, bis sie duften und der Kreuzkümmel einen Hauch dunkler wird. Schwenke dabei ständig, damit nichts verbrennt – verbrannte Gewürze schmecken bitter. Lass alles kurz abkühlen und mahle es dann in der Gewürzmühle oder im Mörser zu einem feinen Pulver. Das frisch gemahlene Masala duftet unvergleichlich viel intensiver als gekauftes Pilaugewürz.","dauer":3,"tipp":"Gewürzmischung in einem Schraubglas luftdicht und dunkel aufbewahren, sie hält sich etwa 2–3 Monate."},{"titel":"Rindfleisch vorgaren","aktion":"koecheln","text":"Gib die Fleischwürfel mit der halbierten Zwiebel, dem angedrückten Knoblauch, den Lorbeerblättern, 1 Teelöffel Salz und einem Teelöffel des frischen Masalas in den Topf und gieße 1 Liter kaltes Wasser an. Bringe alles langsam zum Kochen und schöpfe den grauen Schaum ab, der sich an der Oberfläche sammelt. Schalte dann auf kleinste Hitze und lass das Fleisch 60–75 Minuten halb zugedeckt sanft köcheln, bis es sich mit einer Gabel leicht zerteilen lässt. Seihe die Brühe ab und fange sie auf – du brauchst später etwa 650 ml davon.","dauer":70,"tipp":"Die Brühe nie stark kochen lassen: Sprudelndes Wasser macht das Fleisch faserig und trüb."},{"titel":"Zwiebeln tiefbraun braten","aktion":"braten","text":"Erhitze 5 Esslöffel Öl in einem großen, schweren Topf bei mittlerer Hitze und gib die Zwiebelringe hinein. Brate sie 15–20 Minuten und rühre dabei regelmäßig um, sie sollen erst glasig, dann goldgelb und schließlich tief kastanienbraun werden. Der Duft wird süßlich-nussig; zeigen sich dunkle, kohlige Ränder, schalte sofort die Hitze herunter. Diese dunkle Zwiebelbasis ist das Herzstück des Pilau und färbt später den gesamten Reis.","dauer":18,"tipp":"Nimm ein paar Löffel Brühe dazu, wenn die Zwiebeln anbrennen – so karamellisieren sie weiter, ohne zu verbrennen."},{"titel":"Kartoffeln und Gewürze anbraten","aktion":"anbraten","text":"Gib die abgetropften Kartoffelwürfel zu den Zwiebeln und brate sie 4–5 Minuten, bis sie am Rand leicht Farbe annehmen. Rühre dann Knoblauch, Ingwer und das frisch gemahlene Pilau-Masala ein und röste alles unter Rühren etwa 1 Minute, bis der Duft den ganzen Raum erfüllt. Gib die gewürfelten Tomaten dazu und lass sie 5 Minuten einkochen, bis sie zu einer dicken, öligen Paste zerfallen. Sobald sich das Öl am Rand absetzt, ist die Basis fertig.","dauer":10,"tipp":""},{"titel":"Fleisch und Reis zugeben","aktion":"mischen","text":"Hebe das gegarte Fleisch mit einer Schaumkelle aus der Brühe und rühre es in die Zwiebel-Tomaten-Basis, dann brate es 2 Minuten mit. Gib den abgetropften Reis dazu und wende ihn 2 Minuten, bis die Körner leicht glänzen und mit der Basis überzogen sind. Gieße 650 ml heiße Brühe und 100 ml Kokosmilch an und salze nach Geschmack; die Flüssigkeit sollte etwa einen Fingerbreit über dem Reis stehen. Rühre einmal vorsichtig um und streiche die Oberfläche glatt.","dauer":0,"tipp":""},{"titel":"Aufkochen und quellen lassen","aktion":"daempfen","text":"Bringe den Reis bei starker Hitze zum Kochen, bis an der Oberfläche kleine Dampflöcher entstehen. Decke den Topf sofort fest zu, schalte auf kleinste Stufe und lass den Reis 15 Minuten ungestört garen. Öffne den Deckel nicht, denn der Dampf ist das, was den Reis garen lässt. Nach 15 Minuten ist die Flüssigkeit aufgesogen und die Körner sind fast gar, aber noch leicht bissfest.","dauer":15,"tipp":"Lege ein sauberes Küchentuch zwischen Topf und Deckel, es nimmt Kondenswasser auf, damit der Reis nicht klebrig wird."},{"titel":"Nachquellen lassen","aktion":"ruhen","text":"Nimm den Topf von der Herdplatte und lass ihn mit dem Tuch unter dem Deckel noch 10 Minuten stehen. Durch die Restwärme garen die Körner fertig und die Aromen verbinden sich. Lockere den Reis dann mit einer Gabel von unten nach oben auf, sodass die dunklen Zwiebeln und das Fleisch gleichmäßig verteilt sind. Er sollte körnig, trocken und tief goldbraun aussehen.","dauer":10,"tipp":""},{"titel":"Kachumbari anrichten und servieren","aktion":"garnieren","text":"Schneide die Tomaten in kleine Würfel, die rote Zwiebel in feine Streifen und hacke die Chili und das Koriandergrün. Vermische alles mit Limettensaft und etwas Salz und lasse den Salat 10 Minuten durchziehen. Richte den Pilau auf einer großen Platte an, ziehe einige Röstzwiebeln obenauf und serviere den Salat separat. Die Frische des Kachumbari gleicht die Würze des Reises wunderbar aus.","dauer":10,"tipp":""}],"profitipps":["Die Zwiebeln sind das Geheimnis: lieber 5 Minuten länger braten, bis sie wirklich tief braun, aber nicht schwarz sind.","Immer mit heißer Brühe aufgießen, nicht mit kaltem Wasser – kalte Flüssigkeit stoppt den Garprozess und der Reis wird klebrig.","Den Reis vorher waschen und einweichen, damit die Körner nicht zerbrechen und locker bleiben.","Frisch gemahlenes Pilau-Masala ist deutlich aromatischer als gekauftes Pulver.","Wer es traditionell möchte, nimmt Rind mit Knochen für eine kräftigere Brühe."],"varianten":["Hühnchen-Pilau mit Hähnchenschenkeln und Hühnerbrühe","Kokos-Pilau mit mehr Kokosmilch (Tansania)","Pilau mit Ziegenfleisch zu Festtagen","Vegetarischer Pilau mit Kichererbsen und Kartoffeln"],"beilagen":["Kachumbari","Pili-Pili-Sauce","gebratene Bananen","Joghurt-Raita"],"getraenk":"Gewürztee (Chai) mit Kardamom oder frischer Limetten-Ingwer-Saft","koeche":[],"quellen":[{"titel":"Tastes from the Road – Coconut Pilau from Tanzania","url":"https://www.tastesfromtheroad.com/post/coconut-pilau-from-tanzania"},{"titel":"The Food Dictator – Zanzibar Beef Pilau","url":"https://www.thefooddictator.com/the-hirshon-zanzibar-beef-pilau/print/28476/"}],"bild":"reis","farben":["#8b5a2b","#c68b3e","#f0d9a8"],"schlagworte":["Sansibar","Swahili","Festessen","Gewürzreis","Kokosmilch"],"vegetarisch_moeglich":false,"themen":["fest"]},{"id":"ostafrika-chapati","name":"Chapati (ostafrikanisch, geschichtet)","originalname":"Chapati","kueche":"ostafrika","region":"Kenia / Uganda / Tansania","beliebtheit":79,"hauptkategorie":"vegan","fleischsorte":"","gang":"brot","kurz":"Weiche, goldbraun gefleckte Fladen mit vielen feinen Schichten – das beliebteste Brot Ostafrikas, zum Dippen in Eintöpfe oder als Wrap-Basis.","hintergrund":"Chapati kam durch indische Arbeiter, die Ende des 19. Jahrhunderts die Eisenbahn von Mombasa nach Uganda bauten, nach Ostafrika und wurde dort zur Alltagsspeise. Im Unterschied zum trockenen indischen Roti sind die ostafrikanischen Fladen reichhaltiger und geschichtet: Der Teig wird mit Öl bestrichen, zu einer Schnecke aufgerollt und erneut ausgerollt, so entstehen blättrige Lagen. In Kenia gehört Chapati zu Eintöpfen, Bohnen und Nyama Choma, in Uganda ist es die Hülle des Rolex.","portionen":4,"zeit":{"vorbereitung":30,"garen":25,"ruhen":45},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Teig (8 Fladen)","liste":[{"menge":500,"einheit":"g","name":"Weizenmehl Type 550","hinweis":"oder halb Type 405, halb Type 1050"},{"menge":1,"einheit":"TL","name":"Salz"},{"menge":1,"einheit":"EL","name":"Zucker"},{"menge":3,"einheit":"EL","name":"Pflanzenöl","hinweis":"in den Teig"},{"menge":280,"einheit":"ml","name":"warmes Wasser","hinweis":"ca. 40 °C, nach Bedarf etwas mehr oder weniger"}]},{"gruppe":"Zum Schichten und Braten","liste":[{"menge":6,"einheit":"EL","name":"Pflanzenöl","hinweis":"etwa 4 EL zum Bestreichen, Rest zum Braten"},{"menge":3,"einheit":"EL","name":"Mehl","hinweis":"zum Ausrollen"}]}],"ausruestung":["große Schüssel","Nudelholz","beschichtete oder gusseiserne Pfanne (24–26 cm)","Pinsel","Wendespatel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Mehl, Salz und Zucker ab und gib alles in eine große Schüssel. Erwärme das Wasser auf etwa 40 °C; es soll sich angenehm warm anfühlen, nicht heiß. Lege Nudelholz, Pinsel, Öl, das Extra-Mehl für die Arbeitsfläche und ein sauberes Tuch bereit. Bei den ersten Fladen kannst du ruhig mit mehr Mehl arbeiten, später wirst du sicherer im Umgang mit dem Teig.","dauer":0,"tipp":""},{"titel":"Teig kneten","aktion":"kneten","text":"Gib das Öl und die Hälfte des Wassers zum Mehl und verrühre alles mit der Hand. Gieße unter Kneten nach und nach das restliche Wasser dazu, bis ein weicher, leicht klebriger Teig entsteht. Knete ihn 8–10 Minuten auf der bemehlten Arbeitsfläche, bis er glatt, elastisch und seidig wirkt und beim Eindrücken langsam zurückfedert. Klebt er zu stark, arbeite 1 Esslöffel Mehl ein, ist er fest und rissig, gib einen Schluck Wasser dazu.","dauer":10,"tipp":"Je länger du knetest, desto weicher und elastischer werden die Fladen."},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Forme den Teig zu einer Kugel, bestreiche ihn dünn mit Öl, damit er keine Haut bildet, und decke ihn mit einem feuchten Tuch ab. Lass ihn mindestens 30 Minuten bei Zimmertemperatur ruhen. In dieser Zeit entspannt sich das Gluten, und der Teig lässt sich später leichter hauchdünn ausrollen. Er fühlt sich danach weich und geschmeidig an wie ein Ohrläppchen.","dauer":30,"tipp":""},{"titel":"Teig ausrollen und mit Öl bestreichen","aktion":"ausrollen","text":"Teile den Teig in 8 gleich große Stücke von etwa 100 g. Rolle eines nach dem anderen auf der bemehlten Fläche zu einem dünnen Rechteck von etwa 15 × 30 cm aus. Bestreiche die ganze Fläche mit Öl, das später die Schichten voneinander trennt. Je gleichmäßiger du das Öl verteilst, desto blättriger werden die Fladen.","dauer":0,"tipp":""},{"titel":"Zur Schnecke rollen","aktion":"rollen","text":"Rolle das geölte Teigrechteck von der langen Seite her fest zu einer langen Wurst auf. Wickle diese anschließend wie eine Schnecke zu einer flachen Spirale und stecke das Ende unten ein. Wiederhole das mit allen Stücken und lege die Schnecken nebeneinander unter ein Tuch. Dieses Aufrollen ist der Kniff, der die typischen Lagen erzeugt.","dauer":0,"tipp":"Wer es besonders blättrig mag, rollt die Wurst vor dem Einrollen noch einmal leicht in der Hand lang."},{"titel":"Zweite Ruhe","aktion":"ruhen","text":"Lass die Schnecken nochmals 15 Minuten unter einem Tuch ruhen, damit sich der Teig entspannt. Danach lassen sie sich leichter ausrollen, ohne dass die Schichten zusammenreißen. Du erkennst den richtigen Zeitpunkt daran, dass sich eine Schnecke beim Eindrücken mit dem Daumen weich und nachgiebig anfühlt. Erhitze in dieser Zeit die Pfanne auf mittlerer Stufe.","dauer":15,"tipp":""},{"titel":"Ausrollen","aktion":"ausrollen","text":"Drücke eine Schnecke flach und rolle sie auf der bemehlten Fläche zu einem runden Fladen von etwa 20 cm Durchmesser und 2–3 mm Dicke aus. Arbeite mit leichtem Druck von der Mitte nach außen und drehe den Fladen dabei immer wieder. Er soll rund und gleichmäßig dünn sein, aber nicht reißen. Klebt er, streue eine Prise Mehl darauf.","dauer":0,"tipp":""},{"titel":"Braten","aktion":"braten","text":"Lege den Fladen in die heiße, trockene Pfanne und brate ihn etwa 40 Sekunden, bis sich kleine Blasen zeigen. Wende ihn, bestreiche die gebräunte Seite mit etwas Öl und brate die andere Seite 30–40 Sekunden. Wende ihn noch einmal, bestreiche ihn wieder mit Öl und brate, bis beide Seiten goldbraune Flecken haben und der Fladen aufgeht. Ein leichter Druck mit dem Spatel hilft den Luftblasen, sich zu verteilen. Warmhalten, bis alle Fladen fertig sind.","dauer":20,"tipp":"Die Pfanne soll heiß, aber nicht rauchend sein – zu heiß verbrennt das Öl, zu kühl macht die Fladen trocken."},{"titel":"Warmhalten und servieren","aktion":"anrichten","text":"Stapele die fertigen Chapati in einem sauberen Küchentuch oder in Alufolie, damit sie weich und warm bleiben. Der Dampf macht sie geschmeidig und lässt die Schichten aufgehen. Serviere sie zu Eintöpfen, Bohnen, Linsen, gegrilltem Fleisch oder rolle sie mit Eiern zu einem Rolex. Wer mag, drückt die Fladen vor dem Essen mit den Händen leicht zusammen, dann lockern sich die Lagen auf.","dauer":0,"tipp":""}],"profitipps":["Der Teig muss weich sein: Lieber etwas zu feucht als zu trocken, denn nur so bleiben die Fladen nach dem Braten geschmeidig.","Beide Ruhezeiten nicht auslassen – sonst zieht sich der Teig beim Ausrollen immer wieder zusammen.","Ölen zwischen den Schichten ist wichtig, nicht sparsam sein.","Fertige Chapati halten im Tuch gewickelt bis zu 2 Stunden warm.","Reste lassen sich einfrieren und im Toaster oder in der Pfanne wieder aufbacken."],"varianten":["Mit Milch statt Wasser für einen weicheren Fladen","Mit gemahlenem Kardamom oder Zimt für süße Chapati","Mit geriebenem Gemüse (Karotte, Zwiebel) im Teig","Als Wrap mit Rührei (Rolex)"],"beilagen":["Ndengu (Mungbohneneintopf)","Rinder- oder Hühnereintopf","Nyama Choma","Linsen-Dal"],"getraenk":"Chai (Milchtee mit Ingwer und Gewürzen)","koeche":[],"quellen":[{"titel":"Smithsonian Folklife Festival – Recipe from Kenya: Chapati","url":"https://festival.si.edu/blog/2014/recipe-from-kenya-chapati/"},{"titel":"CS Monitor – In Uganda, rolex is a timeless street food","url":"https://proof.csmonitor.com/World/Africa/2023/0427/In-Uganda-rolex-is-a-timeless-street-food"}],"bild":"brot","farben":["#d8a95a","#a8742a","#f3dcaa"],"schlagworte":["Fladenbrot","Kenia","Alltagsbrot","geschichtet"],"vegetarisch_moeglich":true,"themen":["streetfood"]},{"id":"ostafrika-siga-tibs","name":"Siga Tibs – gebratenes Rindfleisch mit Niter Kibbeh","originalname":"ስጋ ጥብስ (Siga Tibs)","kueche":"ostafrika","region":"Äthiopien","beliebtheit":78,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Zarte Rindfleischwürfel, scharf in würziger Gewürzbutter gebraten und mit Zwiebeln, Knoblauch und grüner Chili – schnell gemacht und typisch äthiopisch.","hintergrund":"Tibs (auch Tebs) gehört zu den beliebtesten Fleischgerichten Äthiopiens und wird in Restaurants wie bei Festen serviert. Das Fleisch wird in kleine Würfel oder Streifen geschnitten und in Niter Kibbeh, der mit Kardamom, Koriander, Bockshornklee und Schwarzkümmel gewürzten geklärten Butter, kräftig gebraten. Anders als die lang geschmorten Wot-Eintöpfe ist Tibs in Minuten fertig. Je nach Region isst man es „tere“ (fast roh), „leb leb“ (kurz gebraten) oder durchgebraten und serviert es auf Injera oder in einem kleinen Tontopf mit glühender Kohle.","portionen":4,"zeit":{"vorbereitung":30,"garen":60,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Niter Kibbeh (Gewürzbutter, reicht für mehrere Gerichte)","liste":[{"menge":250,"einheit":"g","name":"Butter","hinweis":"ungesalzen, gute Qualität"},{"menge":0.5,"einheit":"Stück","name":"kleine Zwiebel","hinweis":"grob gewürfelt"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":"angedrückt"},{"menge":1,"einheit":"EL","name":"frischer Ingwer","hinweis":"in dünnen Scheiben"},{"menge":4,"einheit":"Stück","name":"Kardamomkapseln","hinweis":"leicht zerdrückt"},{"menge":1,"einheit":"TL","name":"Koriandersamen","hinweis":"leicht angedrückt"},{"menge":0.5,"einheit":"TL","name":"Bockshornkleesamen"},{"menge":0.5,"einheit":"TL","name":"Schwarzkümmel (Nigella)"},{"menge":2,"einheit":"Stück","name":"Gewürznelken"},{"menge":1,"einheit":"Stück","name":"kleine Zimtstange"},{"menge":0.25,"einheit":"TL","name":"Kurkuma"}]},{"gruppe":"Für das Tibs","liste":[{"menge":600,"einheit":"g","name":"Rinderfilet oder Hüfte","hinweis":"in 2 cm große Würfel geschnitten, gut parieren"},{"menge":3,"einheit":"EL","name":"Niter Kibbeh","hinweis":"ersatzweise Butterschmalz"},{"menge":2,"einheit":"Stück","name":"rote Zwiebeln","hinweis":"in dünne Spalten geschnitten"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"TL","name":"frischer Ingwer","hinweis":"fein gerieben"},{"menge":2,"einheit":"Stück","name":"grüne Chilischoten","hinweis":"in Ringe, Kerne nach Schärfe"},{"menge":1,"einheit":"Stück","name":"Tomate","hinweis":"entkernt und gewürfelt"},{"menge":1,"einheit":"Zweig","name":"Rosmarin"},{"menge":0.5,"einheit":"TL","name":"schwarzer Pfeffer"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["kleiner Topf mit dickem Boden","feines Sieb oder Passiertuch","schwere Pfanne oder gusseiserne Pfanne"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Parie das Rindfleisch, entferne also Sehnen und Silberhaut, und schneide es in gleichmäßige Würfel von etwa 2 cm. Tupfe die Würfel trocken, denn nasses Fleisch kocht in der Pfanne, statt zu bräunen. Schneide die Zwiebeln in dünne Spalten, hacke Knoblauch und Ingwer, schneide die Chilis in Ringe und würfele die Tomate. Lege alle Zutaten in getrennten Schälchen bereit, denn das Braten geht sehr schnell.","dauer":0,"tipp":""},{"titel":"Niter Kibbeh ansetzen","aktion":"kochen","text":"Schmelze die Butter in einem kleinen Topf bei niedriger Hitze und gib Zwiebel, Knoblauch, Ingwer und sämtliche Gewürze dazu. Lass alles bei kleinster Stufe etwa 30–40 Minuten ganz leise simmern; die Butter darf nicht braun werden. Nach einer Weile steigt ein nussiger, würziger Duft auf, die Butter wird klar und goldgelb und am Boden setzen sich weiße Molkereiweiße und Gewürze ab. Auf dem Rand sammeln sich Schaumreste, die du mit einem Löffel abschöpfst.","dauer":40,"tipp":"Die Gewürze dürfen nur sanft ziehen. Wird die Butter zu heiß, schmeckt das Niter Kibbeh bitter."},{"titel":"Gewürzbutter abseihen","aktion":"abseihen","text":"Nimm den Topf vom Herd und lass die Butter 5 Minuten absetzen. Gieße sie durch ein mit einem sauberen Tuch ausgelegtes Sieb in ein Schraubglas, ohne den Bodensatz aufzuwirbeln. Die fertige, klare, goldfarbene Butter erstarrt beim Abkühlen zu einer festen, duftenden Masse. Im Kühlschrank hält sie sich mehrere Wochen und ist Grundlage für Wot, Tibs, Kitfo und viele andere äthiopische Gerichte.","dauer":5,"tipp":"Wer es eilig hat, nimmt gutes Butterschmalz mit einer Prise gemahlenem Kardamom und Koriander."},{"titel":"Zwiebeln anschwitzen","aktion":"anbraten","text":"Erhitze 1 Esslöffel Niter Kibbeh in einer großen Pfanne bei mittlerer Hitze und brate die Zwiebelspalten 4–5 Minuten an, bis sie weich und an den Rändern leicht gebräunt sind. Sie sollen noch etwas Biss haben und süßlich duften. Nimm sie aus der Pfanne und stelle sie beiseite. So hast du Platz für das scharfe Anbraten des Fleisches.","dauer":5,"tipp":""},{"titel":"Fleisch scharf anbraten","aktion":"braten","text":"Erhitze die Pfanne stark, gib 2 Esslöffel Niter Kibbeh dazu und warte, bis die Butter schäumt und zu rauchen beginnt. Lege die Fleischwürfel in einer Schicht ein, am besten in zwei Portionen, damit die Pfanne nicht abkühlt. Brate sie 2–3 Minuten ohne zu rühren, sodass sich eine braune Kruste bildet, wende dann und brate weitere 1–2 Minuten. Die Würfel sollen außen kräftig gebräunt, innen noch saftig-rosa sein.","dauer":6,"tipp":"Salze erst am Ende – Salz zieht Wasser, und das Fleisch würde schmoren statt rösten."},{"titel":"Aromaten dazugeben","aktion":"anbraten","text":"Gib Knoblauch, Ingwer, Chili und den Rosmarinzweig zum Fleisch und schwenke alles 1 Minute kräftig durch. Der Knoblauch soll duften und leicht Farbe nehmen, aber nicht anbrennen. Streue den Pfeffer darüber und gib die vorgebratenen Zwiebeln wieder in die Pfanne. Die Aromen verbinden sich in der heißen Butter und umhüllen das Fleisch.","dauer":2,"tipp":""},{"titel":"Tomate und Garpunkt","aktion":"schmoren","text":"Rühre die gewürfelte Tomate unter und lasse sie 1–2 Minuten mitgaren, bis sie leicht zerfällt und etwas Saft abgibt. Das Fleisch ist medium, wenn es auf Druck federt und etwa 55–58 °C Kerntemperatur erreicht; für durchgebratenes Tibs lässt du es 3–4 Minuten länger schmoren. Schmecke mit Salz ab und entferne den Rosmarinzweig. Die Sauce sollte kurz und glänzend sein und das Fleisch eng umhüllen.","dauer":4,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Richte das Tibs sofort auf einer warmen Platte oder auf Injera an, solange es zischt und dampft. Garniere es mit frischen Chiliringen und etwas Zwiebel. Reiche dazu Injera, einen scharfen Awaze-Dip aus Berbere und Öl und eventuell Ayib, einen frischen Quark. Gegessen wird mit der Hand: Du reißt ein Stück Injera ab und umfasst damit Fleisch und Zwiebel.","dauer":0,"tipp":""}],"profitipps":["Das Fleisch bei Zimmertemperatur braten, kalt aus dem Kühlschrank würde die Pfanne abkühlen und Saft austreten.","Niter Kibbeh auf Vorrat herstellen – es hält sich gekühlt wochenlang und gibt jedem Gericht Tiefe.","In zwei Portionen braten, damit eine Kruste entsteht und das Fleisch nicht gart statt zu bräunen.","Ein Tontopf mit Holzkohle (Mekelesha) hält das Tibs in Äthiopien am Tisch heiß; ein vorgewärmter Teller tut es auch.","Rosmarin ist typisch für Tibs in Addis Abeba – sparsam einsetzen."],"varianten":["Awaze Tibs mit Berbere-Paste und Senf","Derek Tibs: gebraten bis es knusprig ist","Lamm-Tibs (Yebeg Tibs)","Gemüse-Tibs mit Pilzen und Kartoffeln"],"beilagen":["Injera","Awaze-Dip","Ayib (Frischkäse)","Gomen (Kohlgemüse)"],"getraenk":"Äthiopisches Bier (St. George), Tej oder trockener Rotwein","koeche":[{"name":"Yohanis Gebreyesus","bezug":"Beschreibt in seinem Äthiopien-Buch Niter Kebbeh als zentrale Zutat der äthiopischen Küche, gewürzt mit Kardamom, Koriander und Schwarzkümmel – die Grundlage auch für Tibs.","quelle":"https://www.publishersweekly.com/9781623719630"}],"quellen":[{"titel":"Publishers Weekly – Rezension zu „Ethiopia: Recipes and Traditions from the Horn of Africa“ (Yohanis Gebreyesus)","url":"https://www.publishersweekly.com/9781623719630"}],"bild":"pfanne","farben":["#7a3b1e","#b5651d","#e8c98f"],"schlagworte":["Äthiopien","Niter Kibbeh","schnell","Rindfleisch","Gewürzbutter"],"vegetarisch_moeglich":false,"themen":[]},{"id":"ostafrika-mandazi","name":"Mandazi – ostafrikanische Kokos-Kardamom-Krapfen","originalname":"Maandazi","kueche":"ostafrika","region":"Kenia / Tansania / Uganda","beliebtheit":77,"hauptkategorie":"suess","fleischsorte":"","gang":"gebaeck","kurz":"Luftige, goldene Teigdreiecke mit Kardamom und Kokos – frisch frittiert zum Chai, das Frühstücks- und Straßengebäck der Swahili-Küste.","hintergrund":"Mandazi (oder Maandazi, Mahamri) sind frittierte Teigtaschen, die in Kenia, Tansania und Uganda zu jeder Tageszeit gegessen werden – morgens zum Chai, nachmittags als Snack oder mit Bohnen als Hauptmahlzeit. Die Swahili-Küste verwendet Kokosmilch und Kardamom, in anderen Regionen ist der Teig schlichter und weniger süß. Verwandt sind der westafrikanische Puff-Puff und die portugiesischen Malassadas, deren Teig ähnlich ist. Der Teig wird zu Dreiecken, Rauten oder Kreisen geschnitten und in heißem Öl goldbraun gebacken, bis er aufgeht und hohl wird.","portionen":6,"zeit":{"vorbereitung":30,"garen":20,"ruhen":90},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Teig (ca. 20 Stück)","liste":[{"menge":400,"einheit":"g","name":"Weizenmehl Type 405 oder 550","hinweis":"plus Mehl zum Ausrollen"},{"menge":80,"einheit":"g","name":"Zucker"},{"menge":7,"einheit":"g","name":"Trockenhefe","hinweis":"oder 21 g frische Hefe"},{"menge":1,"einheit":"TL","name":"Kardamom","hinweis":"frisch gemahlen aus ca. 10 Kapseln"},{"menge":0.5,"einheit":"TL","name":"Muskat","hinweis":"frisch gerieben"},{"menge":1,"einheit":"Prise","name":"Salz"},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"Größe M"},{"menge":200,"einheit":"ml","name":"Kokosmilch","hinweis":"lauwarm, aus der Dose"},{"menge":2,"einheit":"EL","name":"Kokosraspeln","hinweis":"ungesüßt"},{"menge":2,"einheit":"EL","name":"Pflanzenöl","hinweis":"in den Teig"}]},{"gruppe":"Zum Frittieren","liste":[{"menge":1,"einheit":"l","name":"Pflanzenöl","hinweis":"neutral, z. B. Erdnuss- oder Rapsöl"}]}],"ausruestung":["Rührschüssel","Nudelholz","breiter Topf oder Fritteuse","Küchenthermometer","Schaumkelle","Küchenpapier"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Mehl, Zucker, Hefe und Gewürze ab und mahle den Kardamom frisch, wenn du Kapseln hast – das Aroma ist unvergleichlich stärker als bei Fertigpulver. Wärme die Kokosmilch auf Handwärme (etwa 35 °C), sie darf nicht heiß sein, sonst stirbt die Hefe. Schlage das Ei in einer kleinen Schale auf und lege Küchenpapier, Thermometer und Schaumkelle bereit. Je besser vorbereitet, desto entspannter das Frittieren später.","dauer":0,"tipp":""},{"titel":"Teig mischen","aktion":"mischen","text":"Vermische Mehl, Zucker, Hefe, Kardamom, Muskat, Salz und Kokosraspeln in einer großen Schüssel. Gib Ei, Öl und Kokosmilch dazu und rühre alles mit einem Holzlöffel zu einem weichen, leicht klebrigen Teig zusammen. Er soll noch etwas an den Fingern haften, aber sich vom Schüsselrand lösen. Fehlt Feuchtigkeit, gib einen Schluck Kokosmilch oder Wasser dazu.","dauer":0,"tipp":""},{"titel":"Kneten","aktion":"kneten","text":"Knete den Teig auf einer bemehlten Fläche 8–10 Minuten durch, bis er glatt, elastisch und geschmeidig ist und nicht mehr klebt. Drücke ihn mit dem Handballen weg, falte ihn zurück und drehe ihn dabei. Der Teig ist fertig, wenn er sich dehnen lässt, ohne zu reißen, und beim Fingerdruck langsam zurückfedert. Zu viel zusätzliches Mehl würde die Mandazi später trocken machen.","dauer":10,"tipp":""},{"titel":"Teig gehen lassen","aktion":"gehen","text":"Forme eine Kugel, gib sie in eine leicht geölte Schüssel und decke sie mit einem feuchten Tuch ab. Lass den Teig an einem warmen, zugfreien Ort 60–90 Minuten gehen, bis er sich sichtbar verdoppelt hat. Beim Eindrücken mit dem Finger soll die Delle langsam zurückkommen. Ist es kühl in der Küche, stelle die Schüssel in den leicht warmen Backofen (30 °C).","dauer":75,"tipp":""},{"titel":"Ausrollen und formen","aktion":"ausrollen","text":"Drücke den Teig leicht flach und rolle ihn etwa 1 cm dick aus. Schneide mit einem scharfen Messer oder Teigrad Rauten oder Dreiecke von etwa 6 cm Kantenlänge. Lege die Stücke auf ein bemehltes Backblech oder Tuch, decke sie ab und lasse sie weitere 15 Minuten ruhen. So blähen sie sich beim Frittieren gleichmäßig auf.","dauer":15,"tipp":""},{"titel":"Öl erhitzen","aktion":"vorbereiten","text":"Erhitze das Öl in einem breiten Topf auf 175–180 °C. Das Öl sollte mindestens 5 cm hoch sein. Kontrolliere die Temperatur mit dem Thermometer oder halte einen Holzlöffelstiel hinein: Steigen ruhige, feine Bläschen auf, passt es. Ist das Öl zu kalt, saugen sich die Mandazi voll Fett, ist es zu heiß, werden sie außen dunkel und innen roh.","dauer":5,"tipp":""},{"titel":"Frittieren","aktion":"frittieren","text":"Gib 4–5 Teigstücke vorsichtig ins heiße Öl, sie sinken kurz ab und steigen dann blubbernd nach oben. Frittiere sie 2–3 Minuten pro Seite und wende sie mit der Schaumkelle, bis sie gleichmäßig goldbraun sind und sich aufblähen. Hebe sie ab, lasse sie kurz abtropfen und lege sie auf Küchenpapier. Frittiere portionsweise, damit die Temperatur nicht abfällt.","dauer":10,"tipp":"Frische Mandazi sind am besten innerhalb der ersten Stunde – sie schmecken warm, außen knusprig und innen weich."},{"titel":"Servieren","aktion":"anrichten","text":"Lasse die Mandazi 5 Minuten abkühlen, damit der heiße Dampf entweicht und die Kruste knusprig bleibt. Bestäube sie nach Wunsch leicht mit Puderzucker oder wälze sie noch warm in Zucker mit Kardamom. Serviere sie mit gewürztem Milchtee (Chai) oder mit Bohnen und Kokossauce als herzhafte Mahlzeit. Reste halten sich luftdicht verpackt 1–2 Tage und lassen sich kurz im Ofen auffrischen.","dauer":0,"tipp":""}],"profitipps":["Ölmenge und Temperatur sind entscheidend: 175–180 °C halten, sonst werden Mandazi fettig oder roh.","Den Teig nicht zu dünn ausrollen, sonst werden die Mandazi flach und trocken.","Wer es herzhaft mag, verwendet weniger Zucker und serviert sie zu Eintöpfen.","Frischer Kardamom macht den Unterschied – gekaufte Pulver sind oft schwächer.","Teig lässt sich über Nacht im Kühlschrank gehen; vor dem Ausrollen auf Zimmertemperatur bringen."],"varianten":["Mahamri: Swahili-Variante mit mehr Kokosmilch und Kardamom, oft dreieckig","Mandazi mit Backpulver statt Hefe für die schnelle Variante","Mit Zimt oder Vanille aromatisiert","Herzhaft mit Kreuzkümmel und Zwiebel"],"beilagen":["Chai","Bohneneintopf","Kokossauce","frische Früchte"],"getraenk":"Chai (gewürzter Milchtee) oder starker Kaffee","koeche":[],"quellen":[{"titel":"African Bites – Mandazi (East African Doughnuts)","url":"https://www.africanbites.com/mandazi-east-african-doughnuts/"}],"bild":"gebaeck","farben":["#c98a3b","#e6b564","#f7e0b0"],"schlagworte":["Frühstück","Frittiertes","Kardamom","Kokos","Swahili"],"vegetarisch_moeglich":true,"themen":["streetfood"]},{"id":"ostafrika-tibs-mit-injera-samuelsson","name":"Tibs mit Schnell-Injera nach Art von Marcus Samuelsson","originalname":"ጥብስ (Ṭibs)","kueche":"ostafrika","region":"Äthiopien","beliebtheit":76,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Blitzschnell gebratene Rinderwürfel in Berbere, Rosmarin und Tomate auf einem schwammigen Fladen – mit Injera in der Kurzfassung mit Sodawasser und frischem Ayib-Käse.","hintergrund":"Tibs ist ein gebratenes Fleischgericht der äthiopischen Küche aus Rind, Lamm oder Ziege, oft mit Zwiebeln, Tomaten und Gewürzen und häufig zischend heiß serviert. Es wird für besondere Anlässe und Feiertage gemacht; ein Reisebericht aus dem 18. Jahrhundert beschreibt es als Fleisch, das zu Ehren eines Gastes serviert wurde. Samuelsson sagt, dass ihn das Gericht an seine äthiopische Familie erinnert, und hat es unter anderem in einem Video bei Tasty vorgeführt. Diese Fassung folgt seinem bei Food Network veröffentlichten Rezept und umfasst auch ein Schnell-Injera mit Sodawasser und Natron, das ohne tagelange Gärung auskommt – ein schneller Ersatz, kein echtes fermentiertes Injera. Das klassische Rezept dazu steht in der App unter „Injera selbst backen“.","portionen":4,"zeit":{"vorbereitung":40,"garen":25,"ruhen":240},"schwierigkeit":2,"zutaten":[{"gruppe":"Schnell-Injera (ergibt 6 Fladen)","liste":[{"menge":130,"einheit":"g","name":"Teffmehl","hinweis":"ersatzweise Vollkornweizenmehl"},{"menge":65,"einheit":"g","name":"Weizenmehl Type 405"},{"menge":0.75,"einheit":"TL","name":"Natron"},{"menge":0.5,"einheit":"TL","name":"Salz"},{"menge":360,"einheit":"ml","name":"Sodawasser","hinweis":"kalt, mit Kohlensäure"},{"menge":60,"einheit":"ml","name":"Naturjoghurt"},{"menge":1,"einheit":"EL","name":"geklärte Butter oder Ghee","hinweis":"plus etwas mehr für die Pfanne"}]},{"gruppe":"Tibs","liste":[{"menge":3,"einheit":"EL","name":"Olivenöl"},{"menge":2,"einheit":"TL","name":"Niter Kibbeh","hinweis":"siehe eigenes Rezept; ersatzweise Ghee"},{"menge":450,"einheit":"g","name":"Rinderfilet (Spitze)","hinweis":"in 2,5-cm-Würfel"},{"menge":0.5,"einheit":"TL","name":"Salz"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":"gehackt"},{"menge":1,"einheit":"Stück","name":"Ingwerstück, etwa 2,5 cm","hinweis":"geschält, gehackt"},{"menge":1,"einheit":"EL","name":"Berbere"},{"menge":0.5,"einheit":"TL","name":"Kreuzkümmel, gemahlen"},{"menge":2,"einheit":"Zweig","name":"Rosmarin","hinweis":"Nadeln gehackt"},{"menge":2,"einheit":"Stück","name":"Jalapeños","hinweis":"in Ringen, für weniger Schärfe entkernen"},{"menge":120,"einheit":"ml","name":"zerkleinerte Dosentomaten"},{"menge":2,"einheit":"EL","name":"Rotweinessig"},{"menge":2,"einheit":"Stück","name":"frische Tomaten","hinweis":"gewürfelt"},{"menge":2,"einheit":"TL","name":"Koriandergrün","hinweis":"gehackt"},{"menge":2,"einheit":"TL","name":"Dijon-Senf"}]},{"gruppe":"Frischer Käse „Ayib“ (optional, ergibt etwa ½ Tasse)","liste":[{"menge":500,"einheit":"ml","name":"Buttermilch","hinweis":"Vollmilch-Buttermilch"},{"menge":2,"einheit":"EL","name":"Zitronensaft"},{"menge":null,"einheit":"","name":"Salz und Pfeffer","hinweis":"nach Geschmack"}]}],"ausruestung":["große Pfanne mit Deckel","feines Sieb","Küchentuch oder Käsetuch","Schöpfkelle (ca. 120 ml)"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Mehle, Natron und Salz ab und stelle Sodawasser, Joghurt und geklärte Butter bereit. Das Rindfleisch schneidest du in gleichmäßige Würfel von ungefähr 2,5 cm, damit alle Stücke in Sekunden gleich schnell garen. Knoblauch, Ingwer, Rosmarinnadeln und Koriander hackst du fein, die Jalapeños schneidest du in Ringe, die frischen Tomaten würfelst du grob. Hole das Fleisch etwa 20 Minuten vor dem Braten aus dem Kühlschrank, damit es nicht eisig in die Pfanne kommt.","dauer":0,"tipp":"Der Teig für das Injera muss mindestens vier Stunden ruhen. Plane diese Zeit vorher ein oder bereite ihn am Vorabend vor."},{"titel":"Injera-Teig anrühren","aktion":"mischen","text":"Verrühre Teffmehl, Weizenmehl, Natron und Salz in einer großen Schüssel mit einem Schneebesen. Gieße das kalte Sodawasser, den Joghurt und die geklärte Butter dazu und verrühre alles zu einem glatten, dünnflüssigen Teig, der wie Crêpeteig vom Löffel läuft. Teff färbt den Teig graubraun. Das Natron reagiert mit Joghurt und Sodawasser und lässt winzige Bläschen entstehen, die später die schwammige Struktur und die typischen Augen bilden.","dauer":0,"tipp":"Das Original wird tagelang fermentiert. Diese Schnellversion braucht nur Ruhe, schmeckt aber milder und weniger sauer."},{"titel":"Teig ruhen lassen und sieben","aktion":"ruhen","text":"Decke die Schüssel ab und lass den Teig mindestens vier Stunden, besser über Nacht, bei Zimmertemperatur ruhen. In dieser Zeit quillt das Mehl, und die Bläschen verteilen sich. Streiche den Teig danach durch ein feines Sieb, um Mehlklümpchen zu entfernen, und rühre ihn kurz um. Er soll dünnflüssig sein; wirkt er zu dick, rührst du einen Schluck Sodawasser unter.","dauer":240,"tipp":""},{"titel":"Ayib zubereiten (optional)","aktion":"koecheln","text":"Erhitze die Buttermilch mit dem Zitronensaft bei niedriger Hitze, bis sie gerade eben simmert, würze mit Salz und Pfeffer und lass sie etwa 15 Minuten ziehen, ohne zu kochen. Die Milch gerinnt dabei zu weißlichen Käsebröckchen, die in einer klaren, gelblichen Molke schwimmen. Gieße alles durch ein mit Tuch ausgelegtes Sieb, spüle die Bröckchen kurz mit kaltem Wasser, bis das ablaufende Wasser klar ist, decke sie ab und lass sie im Kühlschrank bis zu vier Stunden abtropfen. Zum Schluss salzt du den Käse nach Geschmack. Er hält sich im Kühlschrank bis zu einer Woche.","dauer":25,"tipp":"Die Quelle nennt Milch in der Beschreibung und Buttermilch in der Zutatenliste; hier ist die Zutatenliste maßgeblich."},{"titel":"Injera backen","aktion":"braten","text":"Erhitze eine große Pfanne mit etwas geklärter Butter auf mittlerer bis hoher Hitze. Gieße eine Kelle Teig (ungefähr 120 ml) in die Mitte und verteile ihn durch Schwenken spiralförmig nach außen. Backe den Fladen etwa 20 Sekunden offen, bis sich Löcher bilden, dann deckst du die Pfanne zu und backst weitere 30 Sekunden, bis die Oberseite matt und trocken wirkt. Die Unterseite soll hell bleiben, nicht braun. Lege jeden fertigen Fladen auf einen Teller und halte sie unter einem sauberen Tuch warm.","dauer":15,"tipp":"Die erste Kelle ist meist ein Probefladen: Passe Hitze und Teigmenge an."},{"titel":"Aromaten und Gewürze anschwitzen","aktion":"braten","text":"Erhitze Olivenöl und Niter Kibbeh in einer großen Pfanne bei mittlerer bis hoher Hitze und würze die Fleischwürfel mit dem halben Teelöffel Salz. Gib Knoblauch und Ingwer in die Pfanne und schwitze sie eine Minute an, bis es nach beidem duftet. Rühre dann Berbere, Kreuzkümmel und Rosmarin ein. Die Gewürze sollen kurz im Fett rösten und eine tiefrote Paste bilden, aber nicht anbrennen.","dauer":2,"tipp":""},{"titel":"Fleisch scharf anbraten","aktion":"braten","text":"Schalte die Hitze auf hoch, gib das Fleisch und die Jalapeños in die Pfanne und wende alles etwa eine Minute lang, bis die Außenseite der Würfel Farbe nimmt. Das Fleisch soll braun werden, innen aber saftig rosa bleiben, deshalb wird nicht lange gegart und die Pfanne nicht überladen. Die Stücke dürfen zischen und braten, nicht dämpfen. Bei Bedarf brätst du in zwei Portionen.","dauer":2,"tipp":"Tibs lebt vom Tempo: Alles vorbereitet bereitstellen, denn zwischen Pfanne und Teller liegen nur wenige Minuten."},{"titel":"Sauce fertigstellen","aktion":"braten","text":"Rühre die zerkleinerten Tomaten, den Essig, die gewürfelten Tomaten, Koriander und Senf ein und koche alles etwa zwei Minuten, bis das Fleisch außen nicht mehr roh rosa wirkt und die Sauce leicht eindickt. Die Säure aus Essig und Tomate hebt die Wärme der Gewürze, der Senf bindet die Sauce. Schmecke mit Salz ab. Lässt du es länger kochen, wird das Rindfleisch zäh.","dauer":3,"tipp":"Magst du das Fleisch durchgegart, gib eine bis zwei Minuten dazu – dann aber zügig servieren."},{"titel":"Anrichten","aktion":"anrichten","text":"Lege einen oder zwei Injera-Fladen auf Teller und verteile das Tibs mit der Sauce darauf. Setze ein bis zwei Löffel Ayib obenauf. Gegessen wird traditionell mit der Hand: Man reißt Stücke vom Injera ab und fasst damit das Fleisch. Stelle zusätzlich weitere Fladen in die Mitte des Tisches, damit sich alle nachnehmen können. Das Fleisch schmeckt am besten in den ersten Minuten, solange es noch zischend heiß ist und die Sauce am Injera aufquillt.","dauer":0,"tipp":"Berbere zum Nachwürzen und ein paar Tropfen Zitronensaft am Tisch sind gern gesehen."}],"profitipps":["Große Hitze, kurze Zeit: Tibs ist ein Schnellgericht. Zu langes Garen macht Filetspitzen trocken.","Eine schwere Pfanne hält die Temperatur beim Einlegen des Fleisches.","Eine ältere, kürzere Fassung der Quelle brät das Fleisch zuerst separat scharf an und nimmt es heraus, bevor die Sauce entsteht – gut, wenn du mehr Röstaromen möchtest.","Echtes Injera hat einen sauren Teig; kaufst du es fertig im afrikanischen Laden, ist das die beste Ergänzung."],"varianten":["Mit Lammfleisch statt Rind, das ist neben Rind die klassische Fleischwahl.","Mit Brokkoli-Rabe, die in der Tasty-Version kurz gedünstet wird.","Mit Awaze, einer scharfen Paste aus Berbere und Wasser, als Dip am Rand."],"beilagen":["Ayib (frischer Käse)","Gomen (Kohlgemüse)","Misir Wot"],"getraenk":"Tej (Honigwein), Bier oder Ingwertee","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson sagt, Tibs erinnere ihn an seine äthiopische Familie; sein Rezept mit Berbere, Rosmarin und Dijon-Senf wurde bei Food Network und in einem Tasty-Video veröffentlicht.","quelle":"https://www.foodnetwork.com/fnk/recipes/injera-with-tibs-9443725"}],"quellen":[{"titel":"Food Network – Injera with Tibs (Marcus Samuelsson)","url":"https://www.foodnetwork.com/fnk/recipes/injera-with-tibs-9443725"},{"titel":"Tasty – Marcus Samuelsson’s Tibs","url":"https://tasty.co/recipe/marcus-samuelssons-tibs"},{"titel":"Wikipedia – Tibs","url":"https://en.wikipedia.org/wiki/Tibs"},{"titel":"Cyprus Mail – Marcus Samuelsson’s traditional Ethiopian tibs recipe","url":"https://cyprus-mail.com/2021/04/20/marcus-samuelssons-traditional-ethiopian-tibs-recipe"}],"bild":"pfanne","farben":["#9c2a12","#d9732b","#f0d6a8"],"schlagworte":["Äthiopien","Injera","Berbere","Schnellgericht"],"vegetarisch_moeglich":false},{"id":"ostafrika-shiro-wot","name":"Shiro Wot mit selbstgemachtem Berbere","originalname":"ሽሮ ወጥ (Shiro Wot)","kueche":"ostafrika","region":"Äthiopien / Eritrea","beliebtheit":74,"hauptkategorie":"vegan","fleischsorte":"","gang":"eintopf","kurz":"Cremiger, würziger Kichererbsen-Eintopf aus Tonschale – das beliebteste äthiopische Fastengericht, mit selbst gemischtem Berbere.","hintergrund":"Shiro ist ein feines Mehl aus gemahlenen Kichererbsen und Gewürzen, das in Wasser zu einem sämigen Eintopf gekocht wird. Es ist das wichtigste Gericht der Fastenzeit der äthiopisch-orthodoxen Kirche, in der an über 200 Tagen im Jahr auf tierische Produkte verzichtet wird, und gehört deshalb zu den Klassikern der veganen Küche am Horn von Afrika. Serviert wird Shiro heiß und blubbernd in einer kleinen Tonschale (Dist) mit Injera. Das Gewürz Berbere, eine feurige Mischung aus Chili, Bockshornklee, Koriander und weiteren Gewürzen, gibt dem Gericht Farbe und Tiefe.","portionen":4,"zeit":{"vorbereitung":25,"garen":50,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Berbere (selbst gemischt, reicht für mehrere Gerichte)","liste":[{"menge":3,"einheit":"EL","name":"Paprikapulver edelsüß"},{"menge":1,"einheit":"EL","name":"Cayennepfeffer","hinweis":"mehr für schärfere Mischung"},{"menge":1,"einheit":"TL","name":"Bockshornkleesamen"},{"menge":1,"einheit":"TL","name":"Koriandersamen"},{"menge":0.5,"einheit":"TL","name":"Kardamomsamen","hinweis":"aus ca. 8 Kapseln"},{"menge":0.5,"einheit":"TL","name":"schwarze Pfefferkörner"},{"menge":4,"einheit":"Stück","name":"Gewürznelken"},{"menge":0.5,"einheit":"TL","name":"Ingwerpulver"},{"menge":0.25,"einheit":"TL","name":"Zimtpulver"},{"menge":0.25,"einheit":"TL","name":"Muskat","hinweis":"frisch gerieben"},{"menge":1,"einheit":"TL","name":"Salz"}]},{"gruppe":"Für das Shiro","liste":[{"menge":120,"einheit":"g","name":"Kichererbsenmehl","hinweis":"ersatzweise fertiges Shiro-Mehl aus dem Afroshop"},{"menge":2,"einheit":"Stück","name":"große rote Zwiebeln","hinweis":"sehr fein gehackt"},{"menge":4,"einheit":"EL","name":"Pflanzenöl","hinweis":"traditionell fastentauglich; nicht-vegan: Niter Kibbeh"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"EL","name":"frischer Ingwer","hinweis":"fein gerieben"},{"menge":2,"einheit":"EL","name":"selbstgemachtes Berbere"},{"menge":1,"einheit":"EL","name":"Tomatenmark"},{"menge":900,"einheit":"ml","name":"Wasser"},{"menge":1,"einheit":"TL","name":"Salz"}]}],"ausruestung":["Gewürzmühle oder Mörser","mittelgroßer Topf mit dickem Boden","Schneebesen","Holzlöffel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Hacke die Zwiebeln so fein wie möglich, am besten mit dem Messer oder in der Küchenmaschine, denn sie lösen sich später fast im Eintopf auf. Hacke den Knoblauch, reibe den Ingwer fein und siebe das Kichererbsenmehl, damit keine Klümpchen entstehen. Miss die Gewürze für das Berbere ab und stelle Wasser, Öl und Tomatenmark bereit. Bei diesem Gericht geht das Rühren später schnell, deshalb muss alles griffbereit sein.","dauer":0,"tipp":""},{"titel":"Berbere mischen","aktion":"mischen","text":"Röste Bockshornklee, Koriander, Kardamomsamen, Pfefferkörner und Nelken in einer trockenen Pfanne bei mittlerer Hitze etwa 1–2 Minuten, bis sie zu duften beginnen. Schwenke sie dabei ständig, denn besonders Bockshornklee wird schnell bitter. Lass sie abkühlen und mahle sie fein. Vermische sie mit Paprika, Cayennepfeffer, Ingwer, Zimt, Muskat und Salz. Das Berbere duftet nun rauchig, würzig und leicht süßlich – es hält sich im Glas drei Monate.","dauer":3,"tipp":"Für mehr Schärfe gibst du Cayenne, für mehr Farbe Paprika zu. Äthiopisches Berbere enthält oft bis zu 15 Gewürze."},{"titel":"Zwiebeln trocken anschwitzen","aktion":"anbraten","text":"Gib die fein gehackten Zwiebeln ohne Fett in den Topf und erhitze sie bei mittlerer Hitze unter häufigem Rühren etwa 8–10 Minuten, bis das Wasser verdampft ist und sie weich, glasig und leicht goldgelb sind. Dieser Schritt, bekannt aus der äthiopischen Küche, lässt die Zwiebeln viel Wasser abgeben und intensiviert ihre Süße. Haften sie am Boden, gib einen Schluck Wasser dazu und kratze den Ansatz los.","dauer":10,"tipp":""},{"titel":"Öl und Aromaten","aktion":"anbraten","text":"Gib das Öl zu den Zwiebeln und rühre es unter. Füge Knoblauch und Ingwer hinzu und brate beides 1–2 Minuten, bis es duftet und die Zwiebeln leicht glänzen. Die Masse sieht jetzt aus wie eine feine, goldene Paste. Achte darauf, dass der Knoblauch nicht braun wird, sonst schmeckt der Eintopf bitter. Das Öl bindet die Aromen von Zwiebel und Gewürzen und gibt dem späteren Eintopf seinen runden, vollen Körper.","dauer":3,"tipp":""},{"titel":"Berbere und Tomatenmark rösten","aktion":"anbraten","text":"Rühre 2 Esslöffel Berbere und das Tomatenmark ein und röste beides unter Rühren 2–3 Minuten bei niedriger Hitze. Das Gewürz entfaltet dabei sein Aroma, und die Masse färbt sich tiefrot und löst sich leicht vom Topfboden. Bei zu hoher Hitze verbrennt das Berbere schnell und wird bitter; gib im Zweifel einen Löffel Wasser dazu.","dauer":3,"tipp":""},{"titel":"Mit Wasser aufgießen","aktion":"kochen","text":"Gieße 900 ml Wasser unter Rühren in den Topf und löse die Röstaromen vom Boden. Bringe alles zum Kochen. Die Flüssigkeit sollte jetzt tiefrot sein und kräftig nach Berbere und Zwiebel duften. Reduziere dann die Hitze auf mittlere Stufe, damit die Brühe nur leise sprudelt. Probiere die Flüssigkeit ruhig schon jetzt: Sie sollte würzig und deutlich salzig-scharf schmecken, denn das Mehl verdünnt den Geschmack später merklich.","dauer":5,"tipp":""},{"titel":"Kichererbsenmehl einrühren","aktion":"mischen","text":"Streue das gesiebte Kichererbsenmehl in feinem Regen in die köchelnde Brühe und rühre dabei mit dem Schneebesen kräftig, damit keine Klumpen entstehen. Die Masse dickt innerhalb von 1–2 Minuten sichtbar an. Rühre weiter, bis alles glatt und cremig ist. Entstehen doch Klümpchen, kannst du sie mit dem Schneebesen am Topfrand zerdrücken.","dauer":3,"tipp":"Nimm das Mehl portionsweise und rühre ständig: So bleibt der Eintopf glatt."},{"titel":"Köcheln lassen","aktion":"koecheln","text":"Reduziere die Hitze auf die niedrigste Stufe und lass das Shiro 20–25 Minuten bei aufgelegtem Deckel leise köcheln. Rühre alle paar Minuten gründlich über den Topfboden, denn die sämige Masse brennt leicht an. Das Shiro ist fertig, wenn es dick wie Haferbrei ist, glänzt und sich ein roter Ölfilm am Rand zeigt. Der Geschmack hat dann die rohe Mehlnote verloren und schmeckt nussig.","dauer":25,"tipp":"Ist der Eintopf zu dick, rühre etwas heißes Wasser ein, ist er zu dünn, lasse ihn ohne Deckel einkochen."},{"titel":"Abschmecken und servieren","aktion":"anrichten","text":"Schmecke mit Salz ab und gib bei Bedarf etwas mehr Berbere für Schärfe dazu. Fülle das Shiro in eine vorgewärmte Schale und träufle einen Esslöffel Öl oder, wenn du nicht vegan kochst, Niter Kibbeh darüber. Serviere es mit Injera, grünen Chilis und einem Salat aus Tomaten und Zwiebeln. Das Shiro schmeckt am nächsten Tag noch intensiver und lässt sich gut aufwärmen.","dauer":0,"tipp":""}],"profitipps":["Das Mehl immer in die kochende Flüssigkeit streuen, nie die Flüssigkeit zum Mehl geben – so vermeidest du Klumpen.","Zwiebeln ohne Fett vorgaren: Das ist der Äthiopien-Kniff für Tiefe und natürliche Süße.","Nur bei niedriger Hitze köcheln und oft rühren, die Masse brennt sonst an.","Berbere in kleinen Mengen selbst mischen, damit es frisch und aromatisch bleibt.","Shiro schmeckt am zweiten Tag noch besser und lässt sich portionsweise einfrieren."],"varianten":["Shiro Tegabino: mit Tomaten und Zwiebeln im Tontopf bis zum Brodeln gekocht","Shiro Fitfit mit zerzupftem Injera vermengt","Mit Niter Kibbeh statt Öl, an Nicht-Fastentagen","Mit grünen Chilis und Tomaten"],"beilagen":["Injera","Gomen (Kohlgemüse)","Salat aus Tomaten und Zwiebeln","grüne Chilis"],"getraenk":"Äthiopischer Kaffee (Buna) oder Ingwertee","koeche":[{"name":"Yohanis Gebreyesus","bezug":"Sein Äthiopien-Buch behandelt Gerichte aus Hülsenfruchtmehlen und ein eigenes Kapitel zu veganen Fastenspeisen sowie Niter Kebbeh als Grundzutat.","quelle":"https://www.publishersweekly.com/9781623719630"}],"quellen":[{"titel":"Publishers Weekly – Rezension zu „Ethiopia: Recipes and Traditions from the Horn of Africa“ (Yohanis Gebreyesus)","url":"https://www.publishersweekly.com/9781623719630"}],"bild":"eintopf","farben":["#b3401e","#d9732e","#f0c27a"],"schlagworte":["vegan","Fastenspeise","Kichererbsen","Berbere","Äthiopien"],"vegetarisch_moeglich":true,"themen":[]},{"id":"ostafrika-misir-wot","name":"Misir Wot","originalname":"ምስር ወጥ (Misir Wot)","kueche":"ostafrika","region":"Äthiopien","beliebtheit":72,"hauptkategorie":"vegan","gang":"hauptgericht","kurz":"Rote Linsen in feurig-würziger Berbere-Zwiebelsauce, serviert auf Injera – vegan und tiefrot.","hintergrund":"Misir Wot ist ein klassisches äthiopisches Fastengericht (Yetsom Beyaynetu), das während der orthodoxen Fastenzeit ohne tierische Produkte zubereitet wird. Die roten Linsen werden mit sehr viel Zwiebel, Knoblauch, Ingwer und Berbere (einer Gewürzmischung aus Chili, Bockshornklee, Kardamom u. a.) langsam zu einem dickflüssigen Ragout geschmort. Es wird mit Injera gegessen, dem säuerlichen Fladenbrot. Beyaynetu, die Fastenplatte mit mehreren Gemüsegerichten, steht in der TasteAtlas-Liste Afrikas auf Platz 2.","portionen":4,"zeit":{"vorbereitung":20,"garen":50,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Linsen und Basis","liste":[{"menge":250,"einheit":"g","name":"rote Linsen","hinweis":"gewaschen"},{"menge":3,"einheit":"Stück","name":"große rote Zwiebeln","hinweis":"sehr fein gehackt oder gerieben"},{"menge":5,"einheit":"Zehe","name":"Knoblauch","hinweis":"gehackt"},{"menge":1,"einheit":"Stück","name":"Ingwer, daumengroß","hinweis":"gerieben"},{"menge":4,"einheit":"EL","name":"Pflanzenöl oder Niter Kibbeh vegan","hinweis":"nach Wunsch"},{"menge":3,"einheit":"EL","name":"Berbere","hinweis":"Afro-/Gewürzladen oder online"},{"menge":1,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":600,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":4,"einheit":"Stück","name":"Injera","hinweis":"Afro-Laden; Ersatz: dünne Fladenbrote"}]}],"ausruestung":["schwerer Topf","Holzlöffel","Reibe"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Reibe oder hacke die Zwiebeln sehr fein, sie sollen fast zerfallen und die Sauce binden. Hacke Knoblauch, reibe Ingwer, wasche die roten Linsen unter fließendem Wasser, bis das Wasser klar ist. Stelle Berbere, Tomatenmark und Öl bereit. Rote Linsen garen schnell, die Zwiebelbasis braucht dagegen Zeit.","dauer":10,"tipp":""},{"titel":"Zwiebeln trocken garen","aktion":"schmoren","text":"Gib die Zwiebeln ohne Öl in den Topf und erhitze sie bei mittlerer Hitze 15–20 Minuten unter häufigem Rühren, bis sie ihr Wasser abgegeben haben und leicht gebräunt sind. Sie dürfen nicht anbrennen. Dieser Schritt macht die Sauce süß und dick. Spritzt es, reduziere die Hitze. Verwende einen Topf mit dickem Boden, damit die Hitze gleichmäßig wirkt und nichts anbrennt. Die Zwiebeln sind fertig, wenn sie tiefgolden, weich und fast zu einer Paste zerfallen sind.","dauer":20,"tipp":""},{"titel":"Öl, Knoblauch, Ingwer","aktion":"anbraten","text":"Gib Öl, Knoblauch und Ingwer zu den Zwiebeln und brate alles 3–4 Minuten bei niedriger Hitze, bis es duftet. Der Knoblauch soll glasig, nicht braun sein. Das Öl nimmt die Aromen auf und verteilt sie in der Sauce. Der Duft ist das Signal: Sobald es intensiv nach Knoblauch und Ingwer riecht, aber noch nichts bräunt, ist der Moment erreicht. Das Öl trägt die fettlöslichen Aromen in die Sauce. Wer es vegan-traditionell mag, kann das Öl durch gewürztes Pflanzenöl ersetzen.","dauer":5,"tipp":""},{"titel":"Berbere rösten","aktion":"anbraten","text":"Rühre Berbere und Tomatenmark ein und röste die Paste 5 Minuten bei niedriger Hitze, bis sie tief rostrot ist und das Öl am Rand rot schimmert. Rühre ständig und gieße bei Bedarf einen Schuss Wasser nach, damit sie nicht anbrennt. Das Rösten entfaltet den Duft und nimmt dem Gewürz Bitterkeit. Die Paste ist fertig, wenn sie dunkelrot ist und das Öl rot schimmert, außerdem riecht sie würzig und rauchig, nicht scharf-staubig. Rühre ständig, denn Berbere brennt leicht an und wird dann bitter.","dauer":5,"tipp":""},{"titel":"Linsen kochen","aktion":"koecheln","text":"Gib die Linsen und 600 ml Wasser zur Würzpaste, bringe alles zum Kochen und lasse es 20–25 Minuten köcheln. Rühre häufig, denn rote Linsen setzen schnell an. Sie zerfallen zu einem dicken, sämigen Brei. Gib Wasser nach, wenn es zu fest wird. Rührst du häufig, entsteht ein sämiges Püree; lässt du die Linsen dagegen ganz, bleiben sie körniger. Beides ist traditionell. Rote Linsen sind gar, sobald sie sich mit einem Löffel mühelos zerdrücken lassen. Gib heißes Wasser nach, wenn es zu fest wird.","dauer":25,"tipp":""},{"titel":"Abschmecken","aktion":"abschmecken","text":"Salze, probiere und passe Schärfe und Würze an. Das Gericht soll würzig-scharf, leicht süß von den Zwiebeln und rund im Geschmack sein. Mit einem Spritzer Zitronensaft wird es frischer. Die Konsistenz sollte löffelfest sein. Koste mit etwas Abstand zum heißen Topf. Fehlt Tiefe, hilft eine Prise Salz oder etwas Berbere. Ist es zu scharf, gleicht ein Löffel Öl oder eine Prise Zucker aus. Ein Spritzer Zitrone macht es frisch und hebt die Gewürze.","dauer":3,"tipp":""},{"titel":"Ruhen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lasse die Linsen 5 Minuten zugedeckt ruhen. Sie werden dickflüssiger und nehmen Geschmack auf. Wärme in der Zwischenzeit die Injera kurz an. Wärme in der Zwischenzeit die Injera in einer trockenen Pfanne oder in Alufolie bei 100 °C im Ofen an, sodass sie weich und biegsam sind. Decke sie mit einem Tuch ab, damit sie nicht austrocknen.","dauer":5,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Lege Injera auf einen Teller, gib die Linsen in die Mitte und serviere weitere Injera als Löffel. Man reißt ein Stück ab, nimmt damit Linsen auf und isst es mit den Fingern. Dazu passen Salat, Gomen und Ayib. Reste halten 4 Tage im Kühlschrank. Wer mag, ergänzt Beilagen wie Gomen, gekochte Karotten und Salat zu einer Fastenplatte (Beyaynetu). Die Linsen schmecken warm am besten, lassen sich aber gut im Kühlschrank aufbewahren und erneut erhitzen.","dauer":0,"tipp":""}],"profitipps":["Zwiebeln ohne Fett garen – das gibt Süße und Bindung.","Berbere gut anrösten, sonst wird es bitter.","Linsen gut waschen und häufig rühren.","Wasser sparsam nachgießen.","Frische Injera warm servieren."],"varianten":["Mit grünen Linsen","Mit Kichererbsenmehl (Shiro Wot)","Mit Karotten"],"beilagen":["Injera","Gomen (Kohl)","Ayib (Frischkäse)"],"getraenk":"Tej oder schwarzer Tee mit Gewürzen","koeche":[],"quellen":[{"titel":"TasteAtlas – Best Rated Dishes in Africa","url":"https://tasteatlas.com/best-rated-dishes-in-africa"},{"titel":"OkayAfrica – 50 of the Best African Foods","url":"https://okayafrica.com/african-countries-best-food-dishes-cuisine"},{"titel":"Celebrity Cruises – Marcus Samuelsson Doro Wat Pasta","url":"https://www.celebritycruises.com/blog/marcus-samuelsson-doro-wat-pasta-recipe"}],"bild":"eintopf","farben":["#b3401f","#d9822b","#f2c07a"],"schlagworte":["Äthiopien","Linsen","vegan","Fastengericht"],"vegetarisch_moeglich":true},{"id":"ostafrika-samaki-wa-kupaka","name":"Samaki wa Kupaka – Fisch in Kokos-Currysauce","originalname":"Samaki wa Kupaka","kueche":"ostafrika","region":"Sansibar / Tansania / Küste Kenias","beliebtheit":72,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"hauptgericht","kurz":"Kross gebratene Fischsteaks in cremiger Sauce aus Kokosmilch, Tomaten und Gewürzen – ein Klassiker der Swahili-Küste.","hintergrund":"Samaki wa Kupaka stammt von der Küste Ostafrikas, wo Fisch vom Indischen Ozean täglich frisch gefangen wird. Der Name bedeutet etwa „Fisch, der mit Sauce bestrichen wird“: Der Fisch wird zuerst mariniert und gegrillt oder gebraten und anschließend in einer würzigen Kokossauce mit Tamarinde und Kreuzkümmel gezogen. Das Gericht zeigt den indischen und arabischen Einfluss auf die Swahili-Küste. Typisch ist die Säure der Tamarinde, die der cremigen Kokosmilch Frische gibt. Traditionell isst man Samaki wa Kupaka mit Reis, Chapati oder Ugali.","portionen":4,"zeit":{"vorbereitung":25,"garen":35,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Fisch und Marinade","liste":[{"menge":800,"einheit":"g","name":"Fischsteaks oder dicke Filets","hinweis":"z. B. Königsmakrele, Dorade, Zackenbarsch oder Seeteufel"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":"Saft"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"gepresst"},{"menge":1,"einheit":"TL","name":"Kurkuma"},{"menge":1,"einheit":"TL","name":"Salz"},{"menge":3,"einheit":"EL","name":"Pflanzenöl","hinweis":"zum Braten"}]},{"gruppe":"Kokos-Currysauce","liste":[{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"fein gehackt"},{"menge":3,"einheit":"Zehe","name":"Knoblauch"},{"menge":1,"einheit":"EL","name":"frischer Ingwer","hinweis":"gerieben"},{"menge":3,"einheit":"Stück","name":"reife Tomaten","hinweis":"gewürfelt"},{"menge":2,"einheit":"TL","name":"Kreuzkümmel","hinweis":"gemahlen"},{"menge":2,"einheit":"TL","name":"Koriandersamen","hinweis":"gemahlen"},{"menge":1,"einheit":"TL","name":"Kurkuma"},{"menge":0.5,"einheit":"TL","name":"Chilipulver","hinweis":"nach Schärfe"},{"menge":400,"einheit":"ml","name":"Kokosmilch"},{"menge":1,"einheit":"EL","name":"Tamarindenpaste","hinweis":"ersatzweise Saft einer halben Limette"},{"menge":1,"einheit":"Stück","name":"grüne Chili","hinweis":"ganz oder in Ringen"},{"menge":1,"einheit":"Handvoll","name":"Koriandergrün"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["große beschichtete oder gusseiserne Pfanne","breiter Schmortopf mit Deckel","Schaumkelle oder breiter Spatel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Tupfe die Fischsteaks trocken, entferne Gräten mit einer Pinzette und zupfe die Schuppen weg, falls noch vorhanden. Schneide Zwiebeln fein, würfele die Tomaten, presse den Knoblauch und reibe den Ingwer. Miss die Gewürze ab und stelle Kokosmilch, Tamarinde und Koriandergrün bereit. Nimm den Fisch 15 Minuten vor dem Marinieren aus dem Kühlschrank, damit er gleichmäßig gart.","dauer":0,"tipp":""},{"titel":"Fisch marinieren","aktion":"marinieren","text":"Vermenge Limettensaft, 3 Knoblauchzehen, Kurkuma und Salz zu einer Marinade und reibe die Fischsteaks von allen Seiten damit ein. Lass sie 30 Minuten bei Zimmertemperatur oder im Kühlschrank durchziehen. Die Säure der Limette festigt das Fleisch und nimmt den Fischgeruch, das Kurkuma färbt die Oberfläche goldgelb. Länger als 45 Minuten solltest du nicht marinieren, sonst wird das Fleisch mehlig.","dauer":30,"tipp":""},{"titel":"Fisch anbraten","aktion":"braten","text":"Erhitze das Öl in der großen Pfanne bei mittlerer bis hoher Hitze, bis es leicht schimmert. Tupfe die Steaks nochmals trocken und brate sie 2–3 Minuten pro Seite, bis sie goldbraun sind. Lass sie nicht zu lange garen, denn sie ziehen später in der Sauce noch nach. Lege sie dann auf einen Teller und halte sie zugedeckt warm.","dauer":6,"tipp":"Den Fisch beim Wenden nicht bewegen, bevor er sich von allein löst – dann bleibt die Kruste heil."},{"titel":"Zwiebeln und Aromaten","aktion":"anbraten","text":"Gib in dasselbe Fett die Zwiebeln und brate sie bei mittlerer Hitze 6–8 Minuten, bis sie weich und goldgelb sind. Füge Knoblauch und Ingwer hinzu und lass sie 1–2 Minuten mitbraten, bis es intensiv duftet. Die Röststoffe vom Fisch am Pfannenboden geben der Sauce extra Geschmack. Lösche den Ansatz mit einem Schluck Wasser, falls er zu dunkel wird.","dauer":9,"tipp":""},{"titel":"Gewürze und Tomaten","aktion":"anbraten","text":"Rühre Kreuzkümmel, Koriander, Kurkuma und Chilipulver ein und röste sie 30 Sekunden mit den Zwiebeln, bis die Gewürze duften. Gib die gewürfelten Tomaten hinzu und lass sie 8–10 Minuten bei mittlerer Hitze einkochen, bis sie zerfallen und sich das Öl am Rand absetzt. Die Masse soll dick, süßlich-würzig und tiefrot sein.","dauer":10,"tipp":""},{"titel":"Kokosmilch und Tamarinde","aktion":"koecheln","text":"Gieße die Kokosmilch an und rühre sie glatt. Gib die Tamarindenpaste und die ganze Chilischote dazu und lass die Sauce 8–10 Minuten sanft köcheln, bis sie sämig wird und leicht an Farbe gewinnt. Schmecke mit Salz ab; die Sauce soll gleichzeitig cremig, würzig und leicht säuerlich schmecken. Koche sie nicht zu stark, da Kokosmilch sonst gerinnen kann.","dauer":10,"tipp":""},{"titel":"Fisch in die Sauce legen","aktion":"schmoren","text":"Lege die Fischsteaks vorsichtig in die Sauce und löffele diese darüber, sodass sie halb bedeckt sind. Decke den Topf ab und lass den Fisch bei kleinster Hitze 6–8 Minuten ziehen, bis er an der dicksten Stelle weiß und blättrig ist (Kerntemperatur etwa 58–60 °C). Rühre nicht, sonst zerfällt er. Das Fleisch nimmt jetzt den Duft der Gewürze an.","dauer":8,"tipp":"Fisch in dicken Stücken braucht etwas länger – lieber kürzer ziehen lassen und Restwärme nutzen."},{"titel":"Abschmecken und garnieren","aktion":"abschmecken","text":"Probiere die Sauce und balanciere sie aus: Säure mit etwas Limettensaft, Würze mit Salz, Schärfe mit Chili. Streue Koriandergrün darüber und richte den Fisch mit reichlich Sauce an. Die Sauce sollte glänzen und leicht am Löffel haften. Schmeckt sie flach, fehlt meist Säure oder Salz, nicht mehr Gewürz; erst wenn beides stimmt, gib bei Bedarf eine Prise Chili dazu.","dauer":0,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Serviere das Gericht heiß mit Basmatireis, Kokosreis, Chapati oder Ugali, dazu Kachumbari. Mit den Fingern lässt sich der Fisch am besten von der Gräte lösen, und mit Chapati tunkst du die Sauce auf. Wer es frisch mag, reicht Limettenspalten und frische Chili dazu. Stelle auch eine Schale für die Gräten bereit, denn Fisch am Knochen schmeckt besonders saftig.","dauer":0,"tipp":""}],"profitipps":["Fester, ölreicher Fisch wie Königsmakrele oder Thunfisch eignet sich besser als zarter Weißfisch.","Die Gewürze kurz rösten, nicht lange: So bleiben sie aromatisch und nicht bitter.","Kokosmilch nie stark kochen lassen, sonst trennt sich das Fett und die Sauce wird körnig.","Tamarindenpaste kann durch Limettensaft und eine Prise Zucker ersetzt werden.","Der Fisch gart in der Sauce nach – lieber einen Hauch zu früh vom Herd nehmen."],"varianten":["Gegrillter Fisch statt gebraten, wie in Mombasa","Mit Garnelen oder Tintenfisch statt Fisch","Mit Okra und Aubergine in der Sauce","Scharfe Variante mit Pili-Pili"],"beilagen":["Kokosreis","Chapati","Kachumbari","Ugali"],"getraenk":"Frischer Ingwer-Limetten-Saft, kühles Pils oder trockener Weißwein","koeche":[],"quellen":[{"titel":"Flightlink – The Seafood Dishes You Must Try in Zanzibar","url":"https://blog.flightlink.co.tz/?p=129"},{"titel":"TasteAtlas – Best rated dishes in Kenya","url":"https://tasteatlas.com/best-rated-dishes-in-kenya"}],"bild":"fisch","farben":["#d9822b","#f2b84b","#f8e3b0"],"schlagworte":["Swahili","Kokosmilch","Fisch","Sansibar","Curry"],"vegetarisch_moeglich":false,"themen":[]},{"id":"ostafrika-doro-wat-rigatoni-samuelsson","name":"Doro-Wat-Rigatoni nach Art von Marcus Samuelsson","originalname":"Doro Wat Rigatoni","kueche":"ostafrika","region":"Äthiopien trifft Italien (USA)","beliebtheit":72,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Das äthiopische Festtagsgericht Doro Wat als Pastasauce: Hähnchenkeulen in einer dunklen Zwiebel-Berbere-Sauce, auf Rigatoni mit geröstetem Kürbis und Frischkäse.","hintergrund":"Samuelsson hat in seinem Buch „The Rise“ (2020, mit Osayi Endolyn; Rezepte entwickelt mit Yewande Komolafe und Tamie Cook) eine Pasta-Fassung des äthiopischen Doro Wat veröffentlicht und sie in der Sendung „Good Morning America“ als Familienliebling vorgestellt. Die Basis ist wie beim Original eine Menge Zwiebeln, die langsam zu einer tiefbraunen Paste verkochen, dazu Butter, Bockshornklee und die Gewürzmischung Berbere. Statt Injera gibt es Rigatoni, statt der gekochten Eier Butternusskürbis und Ayib, den milden äthiopischen Frischkäse. Es ist eine Heimküchen-Fassung nach der veröffentlichten Rezeptur; das klassische Doro Wat mit Eiern und Injera findest du als eigenes Rezept in dieser App.","portionen":6,"zeit":{"vorbereitung":45,"garen":105,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Sauce","liste":[{"menge":4,"einheit":"Stück","name":"Hähnchenkeulen (Ober- und Unterschenkel am Stück)","hinweis":"zusammen etwa 2,2 kg, Haut abgezogen"},{"menge":2,"einheit":"TL","name":"Salz"},{"menge":0.25,"einheit":"TL","name":"schwarzer Pfeffer"},{"menge":2,"einheit":"Stück","name":"große rote Zwiebeln","hinweis":"geviertelt, etwa 500 g"},{"menge":1,"einheit":"Stück","name":"Ingwerstück, etwa 5 cm","hinweis":"geschält, in Scheiben"},{"menge":8,"einheit":"Zehe","name":"Knoblauch","hinweis":"geschält"},{"menge":115,"einheit":"g","name":"Butter","hinweis":"ersatzweise Niter Kibbeh aus diesem Buch für noch mehr äthiopisches Aroma"},{"menge":1,"einheit":"TL","name":"Bockshornklee, gemahlen"},{"menge":2.5,"einheit":"EL","name":"Berbere","hinweis":"siehe Berbere-Rezept in dieser App"},{"menge":1,"einheit":"Dose","name":"gehackte Tomaten","hinweis":"etwa 800 g"}]},{"gruppe":"Für den Kürbis","liste":[{"menge":900,"einheit":"g","name":"Butternusskürbis","hinweis":"geschält, in 1,5-cm-Würfel"},{"menge":1,"einheit":"EL","name":"Olivenöl"},{"menge":1,"einheit":"TL","name":"Salz"},{"menge":0.25,"einheit":"TL","name":"schwarzer Pfeffer"}]},{"gruppe":"Zum Servieren","liste":[{"menge":450,"einheit":"g","name":"Rigatoni","hinweis":"al dente gekocht"},{"menge":80,"einheit":"ml","name":"Ayib (frischer äthiopischer Käse)","hinweis":"ersatzweise körniger Frischkäse oder Ricotta"},{"menge":null,"einheit":"","name":"Parmesan, gerieben","hinweis":"zum Bestreuen"},{"menge":null,"einheit":"","name":"frisches Basilikum","hinweis":"gezupft"}]}],"ausruestung":["großer Schmortopf (Dutch Oven) mit Deckel","Küchenmaschine oder Stabmixer zum Zerkleinern","Backblech","großer Topf für die Pasta"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Ziehe von den Keulen die Haut ab, am besten mit einem Küchentuch als Grifffläche. Würze die Keulen mit zwei Teelöffeln Salz und dem Pfeffer und lasse sie bei Zimmertemperatur liegen, bis du die Zwiebelbasis angesetzt hast. Viertle die Zwiebeln, schäle Ingwer und Knoblauch und wiege Butter, Berbere, Bockshornklee und Tomaten ab. Der Kürbis wird geschält, entkernt und in ca. 1,5 cm große Würfel geschnitten, damit er gleichmäßig röstet. Heize den Ofen noch nicht vor.","dauer":0,"tipp":"Berbere-Qualität entscheidet: Eine frische, selbst gemischte Mischung duftet intensiver und ist weniger scharf als manche gekauften Mischungen."},{"titel":"Zwiebelpüree herstellen","aktion":"puerieren","text":"Gib Zwiebeln, Ingwer und Knoblauch in die Küchenmaschine und pulsiere, bis ein grobes, noch körniges Püree entsteht. Es soll nicht cremig-glatt werden, sonst verliert die Sauce später Struktur. Das Püree riecht jetzt scharf und frisch nach rohen Zwiebeln, das ändert sich in der nächsten Stunde komplett. Hast du keine Küchenmaschine, hacke alles sehr fein von Hand; das dauert, geht aber genauso.","dauer":0,"tipp":"Wenn die Zwiebelmasse viel Saft abgibt, lässt du sie später einfach länger im offenen Topf einkochen."},{"titel":"Zwiebelbasis langsam garen","aktion":"schmoren","text":"Schmelze die Butter mit dem Bockshornklee in einem großen Schmortopf bei mittlerer bis hoher Hitze. Gib das Zwiebelpüree dazu, rühre einmal um, schalte auf niedrige Hitze und lege den Deckel auf. Lass alles etwa 45 Minuten zugedeckt garen und rühre alle fünf bis zehn Minuten um, damit nichts anbrennt. Die Masse wird nach und nach weicher, süßlich im Duft und färbt sich von blassweiß über goldgelb bis dunkelbraun. Das ist die Seele des Gerichts: Je dunkler und süßer die Zwiebelbasis, desto tiefer die Sauce.","dauer":45,"tipp":"Brennt die Basis an den Rändern an, lieber einen Esslöffel Wasser zugeben und den Boden ablösen, als weiterbrutzeln zu lassen."},{"titel":"Berbere anrösten","aktion":"anbraten","text":"Heize jetzt den Backofen auf 175 °C Ober-/Unterhitze vor (155 °C Umluft). Rühre das Berbere unter die karamellisierte Zwiebelbasis und lass es bei mittlerer Hitze zwei bis drei Minuten rösten, bis es intensiv duftet und die Masse eine tiefrote Farbe annimmt. Das kurze Rösten im Fett öffnet das Aroma der Gewürze; verbrennen darf es dabei nicht, weil Berbere sonst bitter wird. Rühre ständig und nimm den Topf notfalls kurz vom Herd.","dauer":3,"tipp":"Bleibt Berbere zu lange trocken auf dem Boden liegen, wird es bitter. Wasser oder Tomate in Reichweite haben."},{"titel":"Tomaten zugeben und aufkochen","aktion":"koecheln","text":"Gib die gehackten Tomaten dazu, rühre den Boden gut ab und bringe die Sauce bei mittlerer Hitze etwa fünf Minuten zum sanften Simmern. Sie sollte dabei dicklich und tiefrot werden und leise blubbern. Schmecke noch nicht endgültig ab, denn die Sauce reduziert sich im Ofen noch. Fehlt Würze, gib später etwas Salz zu.","dauer":5,"tipp":""},{"titel":"Hähnchen im Ofen schmoren","aktion":"schmoren","text":"Lege die gewürzten Hähnchenkeulen in die Sauce, löffle Sauce über die Oberseite, setze den Deckel auf und schiebe den Topf für etwa eine Stunde in den vorgeheizten Ofen. Das Fleisch ist fertig, wenn es sich am Knochen leicht lösen lässt und eine Gabel ohne Widerstand hineingleitet. Die Sauce soll an den Keulen einen dunklen, glänzenden Überzug bilden. Der Duft nach Zwiebeln, Gewürzen und Butter füllt jetzt die ganze Küche.","dauer":60,"tipp":"Wende die Keulen nach 30 Minuten einmal, damit alle Seiten Sauce abbekommen."},{"titel":"Kürbis rösten","aktion":"backen","text":"Während das Hähnchen schmort, mischst du die Kürbiswürfel mit Öl, Salz und Pfeffer und verteilst sie in einer Lage auf einem Backblech. Röste sie in den letzten 30 bis 35 Minuten der Schmorzeit im selben Ofen und wende sie zwischendurch ein- bis zweimal. Sie sind fertig, wenn sie an den Rändern gebräunt und im Kern weich sind und süßlich nach Karamell duften. Nicht zu eng legen, sonst dämpfen sie statt zu rösten.","dauer":35,"tipp":""},{"titel":"Pasta kochen","aktion":"kochen","text":"Koche die Rigatoni in reichlich Salzwasser nach Packungsanleitung al dente, also bissfest. Schöpfe vor dem Abgießen eine Tasse Nudelwasser ab: Mit einem Schluck davon lässt sich die Sauce später geschmeidig verteilen. Rigatoni sind ideal, weil die Rillen die dunkle Sauce festhalten. Schrecke die Pasta nicht ab.","dauer":10,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Hole das Fleisch aus dem Topf und lege es kurz zur Seite. Rühre die Pasta mit etwas Sauce an und mische die gerösteten Kürbiswürfel unter. Verteile die Rigatoni auf Teller oder Platte, setze die Hähnchenkeulen darauf und gib Löffel von Ayib, Parmesan und frisches Basilikum darüber. Die Mischung aus tiefwürziger, leicht süßer Sauce, mildem Kürbis und frischem Käse ist das Besondere an diesem Gericht. Gleich servieren.","dauer":0,"tipp":"Wer das Fleisch lieber zupft: Löse es vom Knochen und rühre es unter die Pasta, so isst es sich leichter."}],"profitipps":["Zwiebeln nicht hetzen: Die 45 Minuten bei niedriger Hitze bringen Süße und Tiefe; ein schnelles Anbraten ersetzt das nicht.","Ayib (frischer Käse) mildert die Schärfe des Berbere. Wer ihn nicht hat, nimmt körnigen Frischkäse oder Ricotta.","Nudelwasser aufheben: Es bindet die Sauce und macht sie glänzend.","Die Sauce schmeckt am nächsten Tag noch besser und lässt sich gut einfrieren."],"varianten":["Mit gekochten Eiern in der Sauce wie im klassischen Doro Wat.","Mit Hähnchenschenkeln ohne Knochen und kürzerer Schmorzeit.","Vegetarisch mit Pilzen und Kichererbsen statt Hähnchen."],"beilagen":["Grüner Salat mit Zitronendressing","Frisches Brot"],"getraenk":"Kräftiger Rotwein mit weicher Struktur oder ein kühles Lagerbier","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson veröffentlichte die Pasta-Variante des Doro Wat in „The Rise“ und stellte sie als Familiengericht in „Good Morning America“ vor.","quelle":"https://abcnews.com/food/story/marcus-samuelsson-shares-authentic-black-food-recipes-narrative-73837764"}],"quellen":[{"titel":"ABC News – Marcus Samuelsson shares 2 authentic recipes (Doro Wat Rigatoni)","url":"https://abcnews.com/food/story/marcus-samuelsson-shares-authentic-black-food-recipes-narrative-73837764"},{"titel":"Foodwise – Berbere Spice Brown Butter (Marcus Samuelsson, The Rise)","url":"https://foodwise.org/recipe/berbere-spice-brown-butter"},{"titel":"Wikipedia – Marcus Samuelsson","url":"https://en.wikipedia.org/wiki/Marcus_Samuelsson"}],"bild":"nudeln","farben":["#8c2f14","#d0662c","#f0cfa0"],"schlagworte":["Äthiopien","Pasta","Fusion","The Rise"],"vegetarisch_moeglich":false},{"id":"ostafrika-kitfo","name":"Kitfo mit Mitmita, Ayib und Gomen","originalname":"ክትፎ (Kitfo)","kueche":"ostafrika","region":"Äthiopien (Gurage)","beliebtheit":70,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Fein gehacktes, hochwertiges Rindfleisch mit würziger Gewürzbutter und scharfem Mitmita – wie ein äthiopisches Tatar, roh oder leicht angewärmt.","hintergrund":"Kitfo ist das berühmteste Gericht der Gurage im Süden Äthiopiens und gilt als Delikatesse für Feste. Frisch gehacktes, mageres Rindfleisch wird mit Niter Kibbeh, der gewürzten geklärten Butter, und Mitmita, einer scharfen Gewürzmischung mit Vogelaugenchili, vermischt. Man isst es „tere“ (roh), „leb leb“ (kurz angewärmt) oder durchgegart. Dazu gibt es mildes Ayib (frischen Käse), das Gomen (gedünsteter Kohl) und Injera. Roh heißt: absolut frisches Fleisch von einem vertrauenswürdigen Metzger.","portionen":4,"zeit":{"vorbereitung":40,"garen":25,"ruhen":15},"schwierigkeit":2,"zutaten":[{"gruppe":"Mitmita (scharfes Gewürz)","liste":[{"menge":2,"einheit":"EL","name":"getrocknete Vogelaugenchili","hinweis":"oder Cayennepfeffer, gemahlen"},{"menge":1,"einheit":"TL","name":"Kardamomsamen","hinweis":"gemahlen"},{"menge":0.5,"einheit":"TL","name":"Gewürznelken","hinweis":"gemahlen"},{"menge":0.5,"einheit":"TL","name":"Zimt"},{"menge":0.5,"einheit":"TL","name":"Ingwerpulver"},{"menge":1,"einheit":"TL","name":"Salz"}]},{"gruppe":"Für das Kitfo","liste":[{"menge":500,"einheit":"g","name":"Rinderfilet oder Tafelspitz","hinweis":"ganz frisch vom Metzger deines Vertrauens, kalt gehalten"},{"menge":80,"einheit":"g","name":"Niter Kibbeh","hinweis":"siehe Rezept Siga Tibs; ersatzweise Butterschmalz mit Kardamom"},{"menge":1.5,"einheit":"EL","name":"Mitmita","hinweis":"nach Schärfe, zunächst nur 1 EL"},{"menge":1,"einheit":"Prise","name":"Salz"}]},{"gruppe":"Beilagen","liste":[{"menge":150,"einheit":"g","name":"Ayib (frischer, fester Quark oder Hüttenkäse)","hinweis":"gut abgetropft"},{"menge":400,"einheit":"g","name":"Mangold oder Collard Greens (Gomen)"},{"menge":1,"einheit":"Stück","name":"Zwiebel"},{"menge":2,"einheit":"Zehe","name":"Knoblauch"},{"menge":1,"einheit":"EL","name":"Niter Kibbeh oder Öl"},{"menge":4,"einheit":"Stück","name":"Injera","hinweis":"siehe Rezept Injera"}]}],"ausruestung":["sehr scharfes Messer","Schneidebrett","kleine Pfanne","Sieb"],"schritte":[{"titel":"Mise en place und Hygiene","aktion":"vorbereiten","text":"Kitfo ist nur so gut und sicher wie das Fleisch. Kaufe frisches, mageres Filet oder Tafelspitz am selben Tag und halte es bis zum Hacken im Kühlschrank. Reinige Brett, Messer und Hände gründlich und stelle eine kalte Schüssel bereit. Wasche den Mangold, schneide Zwiebel und Knoblauch fein und lege alle Zutaten bereit. Kinder, Schwangere und geschwächte Personen sollten nur die durchgegarte Variante essen.","dauer":0,"tipp":"Frisch gehacktes Fleisch nicht stehen lassen – sofort verarbeiten und servieren."},{"titel":"Mitmita mischen","aktion":"mischen","text":"Röste, falls du Samen verwendest, Kardamom und Nelken kurz in einer Pfanne und mahle sie fein. Vermische die gemahlenen Gewürze mit Chilipulver, Zimt, Ingwer und Salz. Mitmita ist deutlich schärfer als Berbere, daher solltest du es zuerst sparsam dosieren. Prüfe die Schärfe an einer Messerspitze auf der Zunge: Es soll scharf, aber duftend schmecken, nicht verbrannt.","dauer":2,"tipp":""},{"titel":"Gomen dünsten","aktion":"daempfen","text":"Entferne die dicken Stiele vom Mangold und schneide die Blätter in feine Streifen. Brate Zwiebel und Knoblauch in 1 Esslöffel Niter Kibbeh 4–5 Minuten glasig, gib den Mangold mit einem Schuss Wasser dazu und dünste ihn zugedeckt 10–12 Minuten, bis er zart und dunkelgrün ist. Würze mit Salz und Pfeffer und stelle das Gemüse warm. Es bringt eine milde, erdige Note und mildert die Schärfe des Kitfo.","dauer":15,"tipp":""},{"titel":"Ayib vorbereiten","aktion":"vorbereiten","text":"Lass den Quark oder Hüttenkäse in einem Sieb gut abtropfen, bis er krümelig und fest ist. Würze ihn mit einer Prise Salz und rühre ihn mit einer Gabel auf. Ayib ist in Äthiopien ein milder, leicht säuerlicher Frischkäse, der die Schärfe des Kitfo ausgleicht. Stelle ihn bis zum Servieren kalt und nimm ihn erst kurz vor dem Anrichten wieder heraus, damit er frisch und kühl bleibt.","dauer":5,"tipp":""},{"titel":"Fleisch hacken","aktion":"hacken","text":"Schneide das gut gekühlte Fleisch zuerst in dünne Scheiben, dann in Streifen und schließlich mit einem scharfen Messer in sehr feine Würfel, fast hackfleischartig, aber noch mit erkennbarer Struktur. Nutze keinen Fleischwolf, denn das erwärmt und zerquetscht das Fleisch. Entferne dabei Sehnen und Fett. Das Fleisch soll rubinrot und frisch riechen, nicht nach Blut oder Säure.","dauer":15,"tipp":"Das Messer vorher in Eiswasser tauchen oder gut kühlen – so bleibt das Fleisch beim Schneiden kalt."},{"titel":"Butter erwärmen und mischen","aktion":"mischen","text":"Erwärme das Niter Kibbeh in einer kleinen Pfanne, bis es flüssig und lauwarm (etwa 40 °C) ist, aber noch nicht heiß. Gib es mit 1 Esslöffel Mitmita und einer Prise Salz zum Fleisch und vermische alles rasch mit zwei Gabeln, sodass jedes Stück umhüllt ist. Das Fleisch soll glänzend und rot-orange aussehen. Probiere eine kleine Menge und gib bei Bedarf mehr Mitmita dazu.","dauer":3,"tipp":""},{"titel":"Garstufe wählen","aktion":"braten","text":"Für „leb leb“ gibst du das Kitfo 30–60 Sekunden in die Pfanne und rührst es nur an, bis es außen leicht grau und lauwarm ist, innen aber roh bleibt. Für die durchgegarte Variante brätst du es 3–4 Minuten bei mittlerer Hitze, bis es durchgängig braun und krümelig ist (Kerntemperatur mindestens 70 °C). Für „tere“ bleibt es roh. Bei der Zubereitung roher Variante nur makelloses Fleisch verwenden.","dauer":4,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Richte das Kitfo als Häufchen auf einem Injera an. Platziere daneben Gomen und Ayib, sodass die Farben leuchten: rotes Fleisch, grünes Gemüse, weißer Käse. Lege weitere Injera zum Greifen bereit. Serviere sofort, denn das Gericht schmeckt am besten, solange es noch lauwarm ist. Dazu passt ein kräftiger Rotwein oder Bier.","dauer":0,"tipp":""}],"profitipps":["Nur absolut frisches Fleisch vom vertrauenswürdigen Metzger verwenden, am besten am Tag des Einkaufs; für Schwangere und Kinder nur durchgegart.","Von Hand hacken: Der Fleischwolf zerdrückt die Fasern, das Kitfo wird matschig.","Butter nur lauwarm verwenden – heiße Butter gart das Fleisch an und verklumpt.","Mitmita ist viel schärfer als Berbere: lieber nachwürzen als überwürzen.","Ayib und Gomen sind nicht nur Beilagen, sie gleichen Schärfe und Fett aus."],"varianten":["Kitfo leb leb – kurz angewärmt","Kitfo yebesele – durchgegart","Gored Gored – würfelig geschnittenes rohes Rindfleisch","Kitfo mit Kocho (Falschbananen-Brot), wie bei den Gurage"],"beilagen":["Injera","Ayib","Gomen","Kocho"],"getraenk":"Kräftiger Rotwein, äthiopisches Bier oder Tej","koeche":[{"name":"Yohanis Gebreyesus","bezug":"Sein Äthiopien-Buch behandelt das alte Gericht aus rohem Rindfleisch mit Dips und gewürzter Butter und beschreibt Niter Kebbeh als zentrale Zutat der äthiopischen Küche.","quelle":"https://www.publishersweekly.com/9781623719630"}],"quellen":[{"titel":"Publishers Weekly – Rezension zu „Ethiopia: Recipes and Traditions from the Horn of Africa“ (Yohanis Gebreyesus)","url":"https://www.publishersweekly.com/9781623719630"}],"bild":"teller","farben":["#a8321e","#d95f2e","#f0d3a0"],"schlagworte":["Äthiopien","Gurage","Mitmita","Delikatesse","Rindfleisch"],"vegetarisch_moeglich":false,"themen":["fest"]},{"id":"ostafrika-berbere-gewuerzmischung-samuelsson","name":"Berbere-Gewürzmischung nach Art von Marcus Samuelsson","originalname":"በርበሬ (Bärbärä)","kueche":"ostafrika","region":"Äthiopien / Eritrea","beliebtheit":70,"hauptkategorie":"vegan","fleischsorte":"","gang":"sauce","kurz":"Die rotbraune Seele der äthiopischen Küche: selbst geröstet und gemahlen, warm, floral und nur mäßig scharf – für Wot, Tibs, Hähnchen, Fisch, Möhren und sogar Obst.","hintergrund":"Berbere ist eine Gewürzmischung auf Chilibasis, die in Äthiopien und Eritrea in fast jedem Eintopf steckt. Typisch sind außerdem Koriander, Bockshornklee, Knoblauch, Ingwer und weitere Gewürze, die von Familie zu Familie variieren. Samuelsson beschreibt sie als mild, mit süßen und floralen Noten statt reiner Schärfe; in seinem Restaurant Red Rooster würzt er damit Rindertatar und Hähnchen. Dieses Rezept folgt der bei Food Network veröffentlichten Fassung aus „Marcus Off Duty“ (2014), umgerechnet in metrische Einheiten. Ich nenne sie Heimküchen-Fassung, denn echte äthiopische Mischungen enthalten oft Zutaten wie Korarima oder Besobela, die hier nicht erhältlich sind.","portionen":12,"zeit":{"vorbereitung":10,"garen":5,"ruhen":10},"schwierigkeit":1,"zutaten":[{"gruppe":"Für etwa 180 ml Berbere","liste":[{"menge":2,"einheit":"TL","name":"Koriandersamen"},{"menge":1,"einheit":"TL","name":"Bockshornkleesamen"},{"menge":0.5,"einheit":"TL","name":"schwarze Pfefferkörner"},{"menge":6,"einheit":"Stück","name":"Kardamomkapseln","hinweis":"grün"},{"menge":4,"einheit":"Stück","name":"Gewürznelken"},{"menge":3,"einheit":"Stück","name":"Pimentkörner","hinweis":"3 bis 4"},{"menge":25,"einheit":"g","name":"getrocknete Zwiebelflocken","hinweis":"etwa ½ Tasse"},{"menge":5,"einheit":"Stück","name":"getrocknete Chilischoten (Chile de árbol)","hinweis":"entstielt und entkernt; ersatzweise andere kleine scharfe Chilis"},{"menge":3,"einheit":"EL","name":"geräuchertes Paprikapulver"},{"menge":2,"einheit":"TL","name":"Salz"},{"menge":0.5,"einheit":"TL","name":"Zimt, gemahlen"},{"menge":0.5,"einheit":"TL","name":"Ingwer, gemahlen"},{"menge":0.5,"einheit":"TL","name":"Muskatnuss, frisch gerieben"}]}],"ausruestung":["kleine Pfanne","Gewürzmühle oder Mörser","Schüssel","Schraubglas"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Gewürze ab und stelle sie in Griffnähe. Stiele die Chilischoten ab, brich sie auf und schüttle die Kerne aus; trage dabei am besten Einweghandschuhe, damit du dir nicht in die Augen fasst. Die Kardamomkapseln lassen sich mit der Messerflanke aufdrücken, die Samen im Inneren sind das, was du brauchst; die Schalen kannst du mitrösten oder weglassen. Stelle eine Schüssel für das fertige Pulver und ein Schraubglas zum Aufbewahren bereit.","dauer":0,"tipp":"Frische Gewürze: Bockshornklee und Koriander verlieren mit der Zeit ihr Aroma. Kauf kleine Mengen."},{"titel":"Samen trocken rösten","aktion":"braten","text":"Gib Koriander, Bockshornklee, Pfefferkörner, Kardamom, Nelken und Piment in eine kleine, trockene Pfanne und rühre sie bei mittlerer Hitze etwa vier Minuten, indem du die Pfanne schwenkst. Die Gewürze sollen fein duften, leicht dunkler werden und beginnen, zu knistern. Nimm sie sofort vom Herd, wenn der Duft intensiv und warm wird, denn schon kurz danach kippt der Geruch ins Bittere. Bockshornklee ist besonders empfindlich.","dauer":4,"tipp":"Verbrannter Bockshornklee macht die ganze Mischung bitter. Im Zweifel lieber 30 Sekunden früher abbrechen."},{"titel":"Abkühlen lassen","aktion":"kuehlen","text":"Kippe die gerösteten Gewürze in eine flache Schale oder gleich in die Gewürzmühle und lasse sie vollständig auskühlen, etwa zehn Minuten. Warme Gewürze mahlen sich schmierig und verklumpen, weil die ätherischen Öle noch weich sind. Kalt zerspringen sie sauber zu feinem Pulver. Du erkennst den richtigen Zeitpunkt daran, dass sich die Samen in der Hand nicht mehr warm anfühlen und ein trockenes, leicht raschelndes Geräusch machen, wenn du die Schale schüttelst.","dauer":10,"tipp":""},{"titel":"Zusammen mahlen","aktion":"puerieren","text":"Gib die abgekühlten Gewürze zusammen mit Zwiebelflocken und den entkernten Chilis in die Gewürzmühle und mahle alles zu einem feinen Pulver. Eine elektrische Kaffeemühle, die nur für Gewürze gedacht ist, eignet sich gut; im Mörser dauert es länger und wird gröber. Schütte das Pulver in eine Schüssel; es duftet nach Rauch, Wärme und einem Hauch Süße.","dauer":3,"tipp":"Halte beim Öffnen der Mühle kurz den Atem an: Der Chilistaub kitzelt in der Nase."},{"titel":"Restliche Gewürze einrühren","aktion":"mischen","text":"Gib das geräucherte Paprikapulver, Salz, Zimt, Ingwer und Muskatnuss zum Pulver und verrühre alles gründlich mit einem Schneebesen. Das Paprikapulver gibt Farbe und milde Süße, die gemahlenen Gewürze runden ab. Die Mischung soll gleichmäßig dunkelrot aussehen, ohne weiße Salz- oder Hellstellen. Du kannst jetzt probieren, sie schmeckt mehr würzig-warm als scharf.","dauer":0,"tipp":"Eine veröffentlichte Variante röstet zusätzlich vier Knoblauchzehen mit den Samen; das ergibt ein feuchteres Aroma und eine kürzere Haltbarkeit."},{"titel":"Abfüllen und lagern","aktion":"vorbereiten","text":"Fülle das Berbere in ein sauberes, trockenes Schraubglas und lagere es dunkel und kühl. Es hält sich etwa sechs Monate, in dieser Zeit lässt das Aroma jedoch nach. Beschrifte das Glas mit dem Datum und schreibe die Mengen dazu, falls du die Mischung später nachbauen möchtest. Lagere es nicht neben dem Herd oder in der Sonne, denn Wärme und Licht lassen die Farbe verblassen und die Aromen schneller verfliegen. Schüttle das Glas vor jedem Gebrauch einmal, damit sich gröbere Teile gleichmäßig verteilen.","dauer":0,"tipp":""},{"titel":"Anwenden","aktion":"abschmecken","text":"Samuelsson empfiehlt, zu Beginn des Kochens bei Schmorgerichten nach und nach löffelweise Berbere zuzugeben und es anzubraten, bis es duftet. Bei Fisch, Obst oder Salaten streust du es erst kurz vor dem Servieren darüber. Gut passt es zu Rindertatar in brauner Butter, Ricotta auf Sauerteigbrot, Lachs oder Thunfisch mit Limette, Lammkarree sowie Ananas mit Honig und grobem Salz.","dauer":0,"tipp":"Mit der Zeit gewöhnst du dich an die Mischung. Fang vorsichtig an und steigere."}],"profitipps":["Frisch gerösteter Geschmack: Wer Samen röstet und selbst mahlt, bekommt deutlich mehr Aroma als aus der fertigen Dose.","Entkernte Chilis geben Farbe und Wärme; lässt du die Kerne drin, wird die Mischung deutlich schärfer.","Kleinmengen mischen: Lieber alle zwei bis drei Monate neu ansetzen.","Berbere kann Fleisch, Gemüse, Fisch, Butter und sogar Obst würzen."],"varianten":["Berbere-Butter: In Niter Kibbeh einrühren (siehe Rezept).","Mit mehr Chili für eine scharfe Familienfassung.","Gekaufte äthiopische Mischung: Sie enthält oft Korarima und Besobela und schmeckt komplexer."],"beilagen":["Doro Wat","Tibs","Shiro","Berbere-Möhren"],"getraenk":"","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson nennt Berbere seine Geheimwaffe, beschreibt sie als mild, süß-floral und vielseitig und hat das Rezept aus seinem Buch „Marcus Off Duty“ veröffentlicht.","quelle":"https://www.tastingtable.com/692769/marcus-samuelsson-berbere-recipe"}],"quellen":[{"titel":"Food Network – Berbere Roasted Carrots & Fennel with Oranges (Berbere-Rezept, Marcus Off Duty)","url":"https://www.foodnetwork.com/fnk/recipes/berbere-roasted-carrots-and-fennel-with-oranges-9440809"},{"titel":"Tasting Table – Marcus Samuelsson’s Berbere Spice","url":"https://www.tastingtable.com/686528/berbere-spice-blend-recipe-african"},{"titel":"Tasting Table – Berbere Is Marcus Samuelsson’s Secret Weapon","url":"https://www.tastingtable.com/692769/marcus-samuelsson-berbere-recipe"},{"titel":"Wikipedia – Berbere","url":"https://en.wikipedia.org/wiki/Berbere"}],"bild":"dip","farben":["#8a2a12","#c8501c","#e8b36a"],"schlagworte":["Gewürzmischung","Äthiopien","Basis"],"vegetarisch_moeglich":true},{"id":"ostafrika-nyama-choma-sukuma-wiki","name":"Nyama Choma mit Sukuma Wiki und Ugali","originalname":"Nyama Choma","kueche":"ostafrika","region":"Kenia","beliebtheit":68,"hauptkategorie":"fleisch","fleischsorte":"ziege","gang":"hauptgericht","kurz":"Über Glut gegrilltes Ziegenfleisch, serviert mit Maisbrei (Ugali), sautiertem Blattkohl und Kachumbari-Salat.","hintergrund":"Nyama Choma bedeutet auf Suaheli „gegrilltes Fleisch“ und ist Kenias Nationalgericht für gesellige Anlässe. Meist wird Ziege, aber auch Rind oder Schaf, in großen Stücken langsam über Holzkohle gegrillt, nur mit Salz gewürzt und mit den Händen gegessen. Dazu gibt es Ugali, einen festen Maisbrei, Sukuma Wiki (wörtlich „die Woche strecken“), ein günstiges Kohlgemüse, und Kachumbari, einen frischen Tomaten-Zwiebel-Salat. Business Daily Africa berichtet über Nyama Choma in Rankings zu kenianischen Gerichten.","portionen":6,"zeit":{"vorbereitung":30,"garen":90,"ruhen":120},"schwierigkeit":2,"zutaten":[{"gruppe":"Nyama Choma","liste":[{"menge":1.5,"einheit":"kg","name":"Ziegenfleisch oder Lammkeule/Rippen","hinweis":"mit Knochen, in große Stücke; Ersatz Lamm"},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"Pflanzenöl","hinweis":""},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"zerdrückt"},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"Saft"},{"menge":1,"einheit":"TL","name":"schwarzer Pfeffer","hinweis":""}]},{"gruppe":"Sukuma Wiki","liste":[{"menge":500,"einheit":"g","name":"Grünkohl oder Collard Greens","hinweis":"in feine Streifen"},{"menge":2,"einheit":"EL","name":"Pflanzenöl","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"gehackt"},{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":"gewürfelt"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Ugali","liste":[{"menge":300,"einheit":"g","name":"weißes Maismehl (Posho)","hinweis":"Ersatz: feiner Polenta-Grieß"},{"menge":900,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Kachumbari","liste":[{"menge":4,"einheit":"Stück","name":"Tomaten","hinweis":"gewürfelt"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"fein gehackt"},{"menge":1,"einheit":"Stück","name":"Chili","hinweis":"fein gehackt"},{"menge":1,"einheit":"Handvoll","name":"Koriander","hinweis":"gehackt"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":"Saft"}]}],"ausruestung":["Grill mit Deckel und Holzkohle","Alufolie","schwerer Topf","stabiler Holzlöffel"],"schritte":[{"titel":"Fleisch vorbereiten","aktion":"vorbereiten","text":"Schneide das Fleisch in große Stücke von ca. 8–10 cm und löse nur überschüssiges Fett, nicht alles, denn es hält das Fleisch saftig. Tupfe es trocken und reibe es mit Salz, Pfeffer, Knoblauch und Zitronensaft ein. Lege es abgedeckt mindestens 2 Stunden bei Zimmertemperatur oder über Nacht in den Kühlschrank. Das Salz wirkt in dieser Zeit tief ins Fleisch.","dauer":120,"tipp":""},{"titel":"Grill vorbereiten","aktion":"grillen","text":"Fülle den Grill mit Holzkohle und entzünde sie. Warte 25–30 Minuten, bis die Kohle durchgeglüht und mit weißer Asche bedeckt ist. Schichte die Kohle so, dass eine heiße und eine kühlere Zone entsteht. Ziegenfleisch braucht lange, indirekte Hitze, sonst wird es außen schwarz und innen zäh. Du erkennst die richtige Glut daran, dass du die Hand nur 3–4 Sekunden über dem Rost halten kannst. Lege einen Topf Wasser neben die Kohle, falls du längere Zeit grillst, denn die Feuchtigkeit hält das Fleisch saftig und die Temperatur gleichmäßig.","dauer":30,"tipp":""},{"titel":"Fleisch langsam grillen","aktion":"grillen","text":"Lege das Fleisch auf die kühlere Zone des Rosts, schließe den Deckel und grille es 60–90 Minuten bei 140–160 °C. Wende die Stücke alle 15 Minuten und bestreiche sie mit etwas Öl. Das Fleisch ist gar, wenn es sich vom Knochen löst und innen 80–85 °C erreicht. Der Duft nach Rauch und gegrilltem Fleisch soll sich gleichmäßig verbreiten.","dauer":80,"tipp":""},{"titel":"Kruste bräunen","aktion":"grillen","text":"Schiebe das Fleisch zuletzt 3–5 Minuten über die heiße Zone und bräune es von allen Seiten. Es soll knusprig und dunkelbraun werden, ohne zu verbrennen. Wende es ständig. Nimm es dann vom Grill, decke es locker ab und lasse es 10 Minuten ruhen. Achte darauf, dass das Fett nicht in die Glut tropft und Stichflammen verursacht, die das Fleisch rußig machen. Die Kruste ist fertig, wenn sie dunkel, knisternd und stellenweise leicht schwarz ist; innen bleibt das Fleisch saftig und weich.","dauer":10,"tipp":""},{"titel":"Sukuma Wiki braten","aktion":"anbraten","text":"Erhitze das Öl in einem großen Topf, brate die Zwiebel 5 Minuten glasig, gib die Tomaten dazu und koche sie 5 Minuten weich. Füge den Kohl in Portionen zu und schmore ihn 8–10 Minuten, bis er zusammenfällt, aber noch Farbe und Biss hat. Würze mit Salz. Er soll glänzend und frisch grün sein, nicht grau.","dauer":20,"tipp":""},{"titel":"Ugali kochen","aktion":"kochen","text":"Bringe das Wasser mit Salz zum Kochen. Rühre nach und nach das Maismehl mit einem Holzlöffel ein, damit keine Klumpen entstehen. Reduziere die Hitze auf mittel und rühre kräftig 10–12 Minuten, bis der Brei fest wird und sich vom Topfboden löst. Der Ugali soll so fest sein, dass man ihn mit der Hand formen kann.","dauer":15,"tipp":"Rühre kräftig und nutze einen stabilen Löffel; der Brei wird sehr schwer."},{"titel":"Kachumbari mischen","aktion":"mischen","text":"Vermische Tomaten, rote Zwiebel, Chili und Koriander in einer Schüssel. Gib Limettensaft und Salz dazu und lasse den Salat 10 Minuten ziehen. Die Zwiebeln verlieren dabei Schärfe und der Salat wird saftig-frisch. Er bildet den erfrischenden Gegenpart zum fetten Fleisch. Schneide die Zutaten gleichmäßig klein, damit sich Tomaten und Zwiebeln in jedem Bissen mischen. Wenn du einen milderen Salat willst, spüle die Zwiebelwürfel kurz in kaltem Wasser ab. Salze erst direkt vor dem Servieren, sonst wird der Salat wässrig.","dauer":10,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Richte das Fleisch auf einem Holzbrett an, ergänze mit Ugali, Sukuma Wiki und Kachumbari. Traditionell isst man mit den Händen: Man formt ein Stück Ugali, drückt eine Mulde und nimmt damit Gemüse und Fleisch auf. Dazu passt ein kaltes Tusker-Bier. Serviere das Fleisch am besten direkt auf dem Brett und lasse es am Tisch mit einem scharfen Messer in mundgerechte Stücke schneiden. Reiche dazu eine scharfe Pili-Pili-Sauce und Zitrone, damit jeder das Fleisch nach Geschmack nachwürzen kann.","dauer":0,"tipp":""}],"profitipps":["Ziege braucht Zeit – indirekte Hitze und Geduld.","Nur mit Salz würzen, das Fleischaroma steht im Vordergrund.","Ugali kräftig rühren, damit er glatt wird.","Kachumbari kurz ziehen lassen.","Mit den Händen essen."],"varianten":["Mit Rindfleisch oder Lamm","Mit Kochbananen","Mit scharfer Pili-Pili-Sauce"],"beilagen":["Ugali","Sukuma Wiki","Kachumbari","Chapati"],"getraenk":"Kaltes Tusker-Bier oder Tangawizi (Ingwerlimonade)","koeche":[],"quellen":[{"titel":"Business Daily Africa – TasteAtlas ranking: South Africa, Algeria, Tunisia","url":"https://www.businessdailyafrica.com/bd/lifestyle/food-drinks/south-africa-algeria-tunisia-among-best-as-kenyan-dishes--4115578"},{"titel":"OkayAfrica – 50 of the Best African Foods","url":"https://okayafrica.com/african-countries-best-food-dishes-cuisine"},{"titel":"Africa.com – 50 of the best African foods","url":"https://africa.com/here-are-50-of-the-best-african-foods-from-across-the-continent"}],"bild":"braten-scheiben","farben":["#7a3a1a","#d9822b","#4f7a2a"],"schlagworte":["Kenia","Grillen","Ugali","Geselligkeit"],"vegetarisch_moeglich":false},{"id":"ostafrika-rolex-uganda","name":"Ugandischer Rolex (Ei-Chapati-Rolle)","originalname":"Rolex (rolled eggs)","kueche":"ostafrika","region":"Uganda","beliebtheit":68,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"snack","kurz":"Rührei mit Kohl und Tomate, in einen frisch gebratenen Chapati gerollt – das Street-Food-Frühstück aus Kampala für unter einen Dollar.","hintergrund":"Der Rolex ist eines der bekanntesten Straßengerichte Ugandas. Der Name entstand aus „rolled eggs“, Eier, die in Chapati gerollt werden, und ist zugleich ein Wortspiel mit der Luxusuhr. Zubereitet wird er an Straßenständen auf Holzkohlekochern: Eier mit Zwiebel, Kohl, Tomate und Chili werden in der Pfanne zu einem Omelett gebacken, ein Chapati wird daraufgedrückt, das Ganze gewendet und fest eingerollt. Der Snack soll Anfang der 1990er in Jinja erfunden worden sein und wurde bei Studenten der Makerere-Universität in Kampala populär.","portionen":4,"zeit":{"vorbereitung":20,"garen":20,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Für 4 Rolex","liste":[{"menge":8,"einheit":"Stück","name":"Eier","hinweis":"Größe M"},{"menge":4,"einheit":"Stück","name":"Chapati","hinweis":"siehe Rezept Chapati, ersatzweise Weizentortillas"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"sehr fein gewürfelt"},{"menge":100,"einheit":"g","name":"Weißkohl","hinweis":"in feine Streifen geschnitten"},{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":"entkernt und fein gewürfelt"},{"menge":1,"einheit":"Stück","name":"grüne Chili","hinweis":"fein gehackt, nach Schärfe"},{"menge":1,"einheit":"Handvoll","name":"Koriandergrün","hinweis":"grob gehackt, optional"},{"menge":4,"einheit":"EL","name":"Pflanzenöl"},{"menge":null,"einheit":"","name":"Salz und Pfeffer","hinweis":"nach Geschmack"}]}],"ausruestung":["große beschichtete Pfanne","Schneebesen oder Gabel","Pfannenwender"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide Zwiebel in feine Würfel, den Kohl in hauchdünne Streifen und die Tomaten in kleine Würfel; entferne bei der Tomate die Kerne, damit das Ei nicht nass wird. Hacke die Chili fein und das Koriandergrün grob. Lege die Chapati bereit und halte sie warm. Weil die Zubereitung nur Minuten dauert, soll alles fertig vor dir liegen, bevor du die Pfanne anstellst.","dauer":0,"tipp":""},{"titel":"Chapati aufwärmen","aktion":"braten","text":"Erwärme jeden Chapati in einer trockenen Pfanne bei mittlerer Hitze etwa 30 Sekunden pro Seite, bis er weich und biegsam ist und leichte Röstflecken zeigt. Wickle die warmen Fladen in ein Küchentuch, damit sie geschmeidig bleiben. Kalte, steife Chapati reißen später beim Rollen. Selbst gemachte, geschichtete Chapati sind ideal, Tortillas funktionieren aber auch.","dauer":3,"tipp":""},{"titel":"Eier verquirlen","aktion":"aufschlagen","text":"Schlage 2 Eier pro Rolex in eine Schüssel und verquirle sie mit Gabel oder Schneebesen kräftig, bis keine Eiweißschlieren mehr zu sehen sind. Würze mit Salz und Pfeffer. Rühre Zwiebel, Kohl, Tomate, Chili und Koriander unter die Eier. Das Gemüse macht den Rolex saftig und knackig; die Mischung sieht bunt und leicht feucht aus.","dauer":0,"tipp":""},{"titel":"Pfanne vorheizen","aktion":"vorbereiten","text":"Erhitze 1 Esslöffel Öl in einer großen Pfanne bei mittlerer Hitze, bis es leicht schimmert. Schwenke die Pfanne, damit das Öl den Boden gleichmäßig bedeckt. Die Pfanne ist richtig heiß, wenn ein Tropfen Eimasse sofort sanft zu brutzeln beginnt. Zu heiß, und das Ei wird gummiartig und braun, zu kalt, und es klebt.","dauer":2,"tipp":""},{"titel":"Ei-Omelett backen","aktion":"braten","text":"Gieße ein Viertel der Eimasse in die Pfanne und verteile sie mit dem Löffel zu einem Kreis von der Größe des Chapati. Lass das Ei 1–2 Minuten stocken, bis der Rand fest und die Oberfläche noch leicht feucht glänzend ist. Reduziere nötigenfalls die Hitze, damit die Unterseite goldgelb bleibt. Rühre das Ei nicht um, es soll ein flaches, zusammenhängendes Omelett werden, kein Rührei.","dauer":2,"tipp":""},{"titel":"Chapati auflegen und wenden","aktion":"braten","text":"Lege jetzt einen Chapati auf das noch leicht feuchte Ei und drücke ihn mit dem Pfannenwender leicht an. Wende das Ganze mit einer schnellen Bewegung, sodass der Chapati unten und das Ei oben liegt. Brate 30–45 Sekunden weiter, bis das Ei fest und der Chapati knusprig-warm ist. Das Ei klebt jetzt am Fladen und lässt sich in einem Stück herausheben.","dauer":1,"tipp":"Ein großer Pfannenwender oder ein Teller zum Wenden hilft, wenn du Angst vor dem Umdrehen hast."},{"titel":"Aufrollen","aktion":"rollen","text":"Nimm den Fladen mit dem Ei aus der Pfanne und lege ihn mit der Eiseite nach oben auf ein Brett. Gib nach Wunsch ein paar frische Tomatenstücke oder Kohlstreifen darauf, dann rolle ihn fest von einer Seite auf. Wickle den Rolex unten in Backpapier oder Alufolie, damit er sich einhändig essen lässt. Der Rolex ist fertig, wenn er prall, warm und gleichmäßig goldbraun ist.","dauer":1,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Wiederhole den Vorgang mit den übrigen Eiern und Chapati und serviere die Rollen sofort, solange Ei und Fladen warm sind. Dazu passen Chilisauce, frischer Tomatensalat oder Tee mit Milch und Ingwer. Wer mag, füllt zusätzlich gebratenes Hackfleisch, Avocado oder Käse hinein – so wird der Rolex auch zur vollwertigen Mahlzeit.","dauer":0,"tipp":""}],"profitipps":["Das Ei muss beim Auflegen des Chapati noch leicht feucht sein, damit beides verklebt.","Frisch gebackene Chapati sind der Schlüssel – abgepackte Tortillas gehen, schmecken aber weniger authentisch.","Gemüse sehr fein schneiden, sonst reißt das Omelett beim Rollen.","Mit Backpapier einwickeln, so lässt sich der Rolex wie auf der Straße einhändig essen.","Mit etwas Chilisauce oder frischer Chili bekommt der Rolex den typischen Kick."],"varianten":["Mit Hackfleisch (Kikomando-Stil)","Mit Avocado und Käse","Mit gebratenem Rindfleisch und Paprika","Rolex mit Kohl und Karotte statt Tomate"],"beilagen":["Chilisauce","Kachumbari","Chai","frische Mango"],"getraenk":"Milchtee mit Ingwer oder frisch gepresster Fruchtsaft","koeche":[],"quellen":[{"titel":"CS Monitor – In Uganda, rolex is a timeless street food","url":"https://proof.csmonitor.com/World/Africa/2023/0427/In-Uganda-rolex-is-a-timeless-street-food"},{"titel":"Tasting Table – In Uganda, Rolex Isn't Just A Watch, It's A Popular Rolled Egg Dish","url":"https://www.tastingtable.com/1263599/uganda-rolex-watch-popular-rolled-egg-dish"}],"bild":"wrap","farben":["#e3b04b","#c97b2a","#f4e0a8"],"schlagworte":["Streetfood","Uganda","Ei","Frühstück","schnell"],"vegetarisch_moeglich":true,"themen":["streetfood"]},{"id":"ostafrika-shiro-samuelsson","name":"Shiro nach Art von Marcus Samuelsson","originalname":"ሽሮ (Shiro)","kueche":"ostafrika","region":"Äthiopien / Eritrea","beliebtheit":68,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"hauptgericht","kurz":"Cremiger Kichererbsenmehl-Eintopf mit Tomate, Ingwer und Berbere – schnell gekocht, sättigend und im Original auch vegan.","hintergrund":"Shiro ist ein Eintopf aus gemahlenen Kichererbsen oder Ackerbohnen und gehört zu den Grundnahrungsmitteln Äthiopiens und Eritreas; er wird besonders in den Fastenzeiten gegessen und ist meist vegan. Samuelsson verbindet Shiro mit seiner Mutter: Sie brachte es ihm ins Krankenhaus, als er adoptiert wurde. Er bezeichnet es als vegetarisches Grundgericht, vergleichbar mit Kartoffelpüree. In dieser Fassung nach seinem Rezept aus „Marcus Off Duty“ (2014) wird Shiro mit karamellisiertem Knoblauch-Ingwer, Berbere und Dosentomaten gekocht. Das ist eine Heimküchen-Fassung seines veröffentlichten Rezepts mit Mengen in metrischen Einheiten.","portionen":4,"zeit":{"vorbereitung":10,"garen":45,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Für den Shiro (ergibt etwa 700 ml)","liste":[{"menge":1,"einheit":"EL","name":"Olivenöl"},{"menge":1,"einheit":"EL","name":"Niter Kibbeh","hinweis":"gewürzte Butter; für die vegane Variante weglassen und mehr Olivenöl nehmen"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":"gehackt"},{"menge":1,"einheit":"Stück","name":"Ingwerstück, etwa 5 cm","hinweis":"geschält, gehackt"},{"menge":1,"einheit":"EL","name":"Berbere"},{"menge":60,"einheit":"g","name":"Kichererbsenmehl","hinweis":"Besan oder Gram-Flour, im Bioladen oder Asia-/Indienladen"},{"menge":240,"einheit":"ml","name":"zerkleinerte Dosentomaten"},{"menge":360,"einheit":"ml","name":"Wasser","hinweis":"plus nach Bedarf mehr"},{"menge":null,"einheit":"","name":"Salz und schwarzer Pfeffer","hinweis":"nach Geschmack"},{"menge":null,"einheit":"","name":"Injera","hinweis":"zum Servieren, optional"}]}],"ausruestung":["Pfanne oder mittelgroßer Topf","Schneebesen","Holzlöffel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Hacke Knoblauch und Ingwer fein und stelle Berbere, Kichererbsenmehl, Tomaten und Wasser bereit. Messe das Mehl genau ab, denn zu viel Mehl macht den Shiro pappig, zu wenig lässt ihn wässrig. Das Niter Kibbeh sollte weich oder flüssig sein; wenn du es neu machst, findest du das Rezept in dieser App. Stelle einen Schneebesen bereit, denn das Mehl muss zügig eingerührt werden.","dauer":0,"tipp":"Siebe das Kichererbsenmehl vorher, wenn es klumpig ist."},{"titel":"Fett erhitzen","aktion":"anbraten","text":"Erhitze das Olivenöl mit zwei Teelöffeln Niter Kibbeh in einer weiten Pfanne bei mittlerer bis hoher Hitze, bis die Butter schmilzt und leicht schäumt. Der Duft nach gewürzter Butter steigt auf. Die Hitze soll hoch genug sein, damit Knoblauch und Ingwer im nächsten Schritt kurz anbraten, aber nicht verbrennen.","dauer":1,"tipp":""},{"titel":"Knoblauch, Ingwer und Berbere anschwitzen","aktion":"anbraten","text":"Gib Knoblauch, Ingwer und Berbere in die Pfanne und rühre alles mit dem Schneebesen etwa zwei Minuten, bis die Mischung duftet und leicht andickt. Berbere färbt das Fett tiefrot. Die Gewürze sollen rösten, nicht dunkel werden, und der Knoblauch darf nicht bitter braten. Nimm bei Bedarf die Pfanne kurz vom Herd.","dauer":2,"tipp":""},{"titel":"Kichererbsenmehl einrühren","aktion":"mischen","text":"Rühre das Kichererbsenmehl rasch und gründlich in die Gewürzpaste, denn die Masse zieht an und verklumpt leicht. Du erhältst eine dicke, rötliche Paste. Schlage sie mit dem Schneebesen glatt, bevor du fortfährst; kleine Klümpchen löst du am besten jetzt mit dem Schneebesen am Pfannenrand. Sie entstehen vor allem, wenn das Mehl zu lange ungerührt am Boden liegt, deshalb bleibt der Schneebesen die ganze Zeit in Bewegung.","dauer":1,"tipp":"Das Mehl vorher nicht anbräunen, sonst wird der Eintopf bitter."},{"titel":"Tomaten und Wasser zugeben","aktion":"koecheln","text":"Rühre die zerkleinerten Tomaten, 240 ml Wasser und den restlichen Teelöffel Niter Kibbeh ein. Die Mischung wird zunächst dünnflüssig und löst sich vom Mehl; rühre, bis keine Klümpchen mehr zu sehen sind. Bringe sie unter Rühren zum Sieden und stelle dann die Hitze herunter, sodass sie nur noch leise blubbert.","dauer":3,"tipp":""},{"titel":"Köcheln lassen","aktion":"koecheln","text":"Lass den Shiro mindestens 10 Minuten, für ein volleres Aroma bis zu 45 Minuten bei niedriger Hitze sanft köcheln und rühre immer wieder um, damit nichts am Boden ansetzt. Gieße bei Bedarf einen Schuss Wasser nach. Er wird mit der Zeit dicker und satter in der Farbe. Der rohe Mehlgeschmack verschwindet erst nach einigen Minuten Köcheln, achte also darauf, dass die Masse nicht mehr mehlig riecht. Die restlichen 120 ml Wasser gibst du nach Bedarf in kleinen Schlucken nach.","dauer":30,"tipp":"Die Quelle empfiehlt mindestens 10 Minuten und höchstens 45; je länger, desto mehr Tiefe."},{"titel":"Konsistenz prüfen","aktion":"abschmecken","text":"Der Shiro ist fertig, wenn er die Dicke von dickflüssiger Buttermilch hat und am Löffel haftet, ohne zu klumpen. Beim Abkühlen zieht er noch weiter an. Ist er zu dick, rührst du etwas heißes Wasser unter. Ist er zu dünn, lässt du ihn ein paar Minuten ohne Deckel einköcheln. Er sollte glänzen und eine sanfte, orangerote Farbe haben, ohne dass sich Fett absetzt.","dauer":3,"tipp":""},{"titel":"Abschmecken und servieren","aktion":"anrichten","text":"Schmecke den Shiro mit Salz und Pfeffer ab. Er soll würzig, leicht scharf und mit einer feinen Säure aus der Tomate schmecken. Serviere ihn auf Injera, löffle ihn über Ofengemüse oder Reis, oder iss ihn zu einer Mahlzeit als Beilage. Samuelsson schlägt außerdem vor, ihn über geröstetes Gemüse oder Brokkoli als leichtes Mittagessen zu geben.","dauer":0,"tipp":"Mit etwas Zitronensaft und gehackten Kräutern wird er frischer."}],"profitipps":["Das Mehl zügig in die Würzpaste einrühren, dann bleibt der Eintopf glatt.","Nicht zu früh abbrechen: Erst nach einigen Minuten Kochen schmeckt das Mehl nicht mehr roh.","Shiro dickt beim Abkühlen nach; bei der Konsistenz also lieber etwas dünner lassen.","Vegane Variante: Niter Kibbeh weglassen und stattdessen Olivenöl nehmen."],"varianten":["Shiro Tegamino: im Tontöpfchen blubbernd serviert, mit mehr Öl und Gewürzen.","Shiro Fit-Fit: Der Eintopf wird mit zerrissenem Injera vermischt und mit dem Löffel gegessen.","Mit Fleisch (Bozena Shiro) in der nicht veganen Fassung."],"beilagen":["Injera","Reis","Geröstetes Gemüse","Salat"],"getraenk":"Äthiopischer Kaffee oder Ingwertee","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson nennt Shiro ein vegetarisches Grundgericht Äthiopiens und verbindet es mit der Erinnerung an seine Mutter; sein Rezept erschien in „Marcus Off Duty“ (2014).","quelle":"https://www.foodnetwork.com/fnk/recipes/shiro-ethiopian-chickpea-spread-9442201"}],"quellen":[{"titel":"Food Network – Shiro (Ethiopian Chickpea Spread), Marcus Samuelsson","url":"https://www.foodnetwork.com/fnk/recipes/shiro-ethiopian-chickpea-spread-9442201"},{"titel":"First We Feast – The 10 Dishes That Made My Career: Marcus Samuelsson","url":"https://amp.firstwefeast.com/features/marcus-samuelsson-career-changing-dishes"},{"titel":"Wikipedia – Shiro (food)","url":"https://en.wikipedia.org/wiki/Shiro_(food)"}],"bild":"eintopf","farben":["#b5441c","#e08a3c","#f0d6a0"],"schlagworte":["Äthiopien","Kichererbsen","Fastengericht","vegan möglich"],"vegetarisch_moeglich":true},{"id":"ostafrika-kitfo-mit-awase-samuelsson","name":"Kitfo mit Awase nach Art von Marcus Samuelsson","originalname":"ክትፎ (Kitfo)","kueche":"ostafrika","region":"Äthiopien (Gurage)","beliebtheit":66,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"vorspeise","themen":["fest"],"kurz":"Das äthiopische Festtagsgericht: fein gewürfeltes Rinderfilet, nur lauwarm in Gewürzbutter geschwenkt, mit Berbere-Meerrettich-Dip und geröstetem Brot.","hintergrund":"Kitfo stammt aus der Küche der Gurage in Äthiopien und besteht aus fein gehacktem rohem Rindfleisch, das mit Gewürzbutter und Chilimischung gewürzt wird. Es gilt als Gericht für besondere Anlässe; wird es nur leicht angewärmt, heißt es „leb leb“. Samuelsson stellt in seinem Red-Rooster-Kochbuch (2016) eine Version mit Gewürzbutter nach der Art vom Volk seiner Frau Maya (Gurage) vor. Er hat Kitfo auch im Red Rooster serviert und beschreibt es als warmes Tatar, das traditionell zu Feiern und spirituellen Anlässen gereicht wird. Dies ist eine Heimküchen-Fassung der veröffentlichten Rezeptur in metrischen Einheiten. Wichtiger Hinweis: Das Gericht enthält rohes Rindfleisch; lies die Hygienehinweise unten.","portionen":4,"zeit":{"vorbereitung":35,"garen":15,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Awase (Dip)","liste":[{"menge":2,"einheit":"EL","name":"Olivenöl"},{"menge":3,"einheit":"EL","name":"Berbere"},{"menge":1,"einheit":"TL","name":"Cayennepfeffer"},{"menge":1,"einheit":"EL","name":"Meerrettich","hinweis":"frisch gerieben, ersatzweise aus dem Glas"},{"menge":1,"einheit":"Stück","name":"Zitrone, Saft"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Kitfo","liste":[{"menge":2,"einheit":"EL","name":"Gewürzbutter (siehe unten)","hinweis":"plus etwas mehr bei Bedarf; ersatzweise Niter Kibbeh aus diesem Buch"},{"menge":2,"einheit":"Stück","name":"Schalotten","hinweis":"fein gehackt"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"Stück","name":"Jalapeño","hinweis":"fein gehackt, nach Wunsch entkernt"},{"menge":1,"einheit":"EL","name":"Berbere"},{"menge":1,"einheit":"TL","name":"Rotweinessig"},{"menge":1,"einheit":"TL","name":"scharfer Senf","hinweis":"die Quelle nennt „Chinese mustard“; ersatzweise scharfer Senf, z. B. Dijon"},{"menge":450,"einheit":"g","name":"Rinderfilet","hinweis":"absolut frisch, von Fett und Sehnen befreit, fein gewürfelt"},{"menge":null,"einheit":"","name":"Salz und Pfeffer","hinweis":"nach Geschmack"},{"menge":null,"einheit":"","name":"Vollkornbrot oder Injera","hinweis":"zum Servieren"}]},{"gruppe":"Gewürzbutter nach Gurage-Art (halbe Menge der Quelle, ergibt etwa 350 ml)","liste":[{"menge":450,"einheit":"g","name":"ungesalzene Butter"},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"Stück","name":"Schalotte","hinweis":"fein gehackt"},{"menge":1,"einheit":"Stück","name":"Ingwerstück, etwa 2,5 cm","hinweis":"geschält, in Scheiben und angedrückt"},{"menge":2.25,"einheit":"TL","name":"Koriandersamen"},{"menge":1.5,"einheit":"TL","name":"Kreuzkümmelsamen"},{"menge":0.75,"einheit":"TL","name":"Ajowan","hinweis":"Samen"},{"menge":0.75,"einheit":"TL","name":"Bockshornkleesamen"},{"menge":0.5,"einheit":"TL","name":"schwarzer Pfeffer, frisch gemahlen"},{"menge":0.25,"einheit":"TL","name":"Zimt, gemahlen"},{"menge":0.25,"einheit":"TL","name":"Kurkuma, gemahlen"}]}],"ausruestung":["sehr scharfes Messer und eigenes Brett für rohes Fleisch","kleiner Topf","große Pfanne","feines Sieb mit Käsetuch","kleine Schüsseln"],"schritte":[{"titel":"Hygiene und Mise en place","aktion":"vorbereiten","text":"Kitfo wird mit rohem Rindfleisch zubereitet: Kaufe das Filet am Tag der Zubereitung bei einem Metzger deines Vertrauens, bewahre es bis zur Verarbeitung kalt auf und verarbeite es sauber. Schwangere, kleine Kinder, ältere Menschen und Personen mit geschwächtem Immunsystem sollten kein rohes Fleisch essen; für sie gibt es unten eine durchgegarte Variante. Reinige Messer, Brett und Hände gründlich und benutze für das rohe Fleisch ein eigenes Brett. Schalotten, Knoblauch und Jalapeño hackst du fein und stellst alle anderen Zutaten bereit.","dauer":0,"tipp":"Rinderfilet ist besonders für rohe Gerichte geeignet, weil es zart und fettarm ist. Achte aber darauf, dass es nie warm wird."},{"titel":"Gewürzbutter ansetzen","aktion":"schmoren","text":"Schmelze die Butter in einem kleinen Topf bei niedriger Hitze und gib Knoblauch, Schalotte, Ingwer und alle Gewürze hinein. Lass alles etwa 30 Minuten sehr sanft ziehen, ohne dass die Milchbestandteile braun werden: Die Butter soll nur leise blubbern. Sie wird goldgelb und riecht nach Koriander, Kreuzkümmel und Bockshornklee, leicht süßlich und würzig. Schöpfe Schaum und schwimmende Gewürzkörner ab, lass die Butter zehn Minuten stehen, damit sich die Milchfeststoffe absetzen, und gieße sie durch ein mit Tuch ausgelegtes Sieb.","dauer":40,"tipp":"Du brauchst für das Kitfo nur zwei Esslöffel. Den Rest bewahrst du abgedeckt im Kühlschrank auf, die Butter hält mehrere Monate."},{"titel":"Awase anrühren","aktion":"mischen","text":"Erhitze das Olivenöl in einer großen Pfanne auf mittlerer Hitze und rühre Berbere, Cayenne, Meerrettich, Zitronensaft und eine Prise Salz ein. Die Paste soll nach ein bis zwei Minuten glänzen, rot sein und scharf-würzig riechen. Der Meerrettich bringt eine frische Schärfe, die die Butter später ausgleicht. Löffle den Dip in ein Schälchen, ohne die Pfanne auszuwischen: Die Reste würzen die nächste Zutat.","dauer":2,"tipp":"Der Awase eignet sich laut Samuelsson auch als Dip für Gemüse, Sauce zu gegrilltem Fisch oder als Lammgewürz."},{"titel":"Kitfo-Basis kochen","aktion":"anbraten","text":"Erhitze zwei Esslöffel Gewürzbutter in derselben Pfanne bei mittlerer Hitze. Gib Schalotten, Knoblauch und Jalapeño dazu und schwitze alles an, bis es weich ist. Rühre das Berbere unter und füge bei Bedarf etwas mehr Butter hinzu, wenn die Pfanne trocken wirkt. Gib den Rotweinessig dazu, salze leicht und lass alles zwei bis drei Minuten köcheln, bis ein Teil der Flüssigkeit verdampft ist. Rühre den Senf ein und koche eine weitere Minute. Die Basis riecht nun kräftig, scharf und buttrig. Gib sie in eine Schüssel und halte sie warm, die Pfanne bleibt unausgewischt.","dauer":6,"tipp":""},{"titel":"Brot rösten","aktion":"braten","text":"Lege das Vollkornbrot in die Pfanne mit den Resten der Gewürzbutter und röste es etwa zwei Minuten pro Seite bei mittlerer Hitze, bis es knusprig und goldbraun ist. Es saugt dabei die Aromen auf und wird zum Löffel für das Tatar. Du kannst es auch durch Injera ersetzen, wenn du welches hast. Stelle die Brotscheiben zum Servieren zur Seite.","dauer":4,"tipp":""},{"titel":"Fleisch würfeln","aktion":"schneiden","text":"Schneide das gut gekühlte Filet in dünne Scheiben, die Scheiben in Streifen und die Streifen in sehr kleine, etwa 3 bis 4 mm große Würfel. Arbeite zügig und mit einem scharfen Messer, damit das Fleisch nicht zerquetscht wird. Kitfo wird traditionell nicht durch den Fleischwolf gedreht, denn die Struktur soll erhalten bleiben. Hast du viel Zeit gebraucht, lege das Fleisch bis zum Mischen kurz in den Kühlschrank.","dauer":10,"tipp":"Wer das Fleisch vorher 20 Minuten ins Gefrierfach legt, schneidet leichter und sauberer."},{"titel":"Fleisch mit der Basis vermischen","aktion":"mischen","text":"Würze das gewürfelte Filet in einer Schüssel mit Salz und Pfeffer und rühre die warme Gewürzbasis ein. Die Basis soll warm, aber nicht heiß sein, damit das Fleisch nur lauwarm wird, ohne zu garen. Die Masse färbt sich dabei rötlich-braun und glänzt vom Butterfett. Schmecke ab: Sie darf kräftig nach Gewürzen schmecken, scharf und leicht säuerlich.","dauer":2,"tipp":"Es gibt drei klassische Garstufen: roh, „leb leb“ (leicht angewärmt) und durchgegart. Je heißer die Basis, desto weiter gart das Fleisch."},{"titel":"Anrichten","aktion":"anrichten","text":"Richte das Kitfo auf einer Platte an, stelle das geröstete Brot oder Injera und den Awase-Dip dazu. Gegessen wird in kleinen Bissen: Man reißt ein Stück Brot ab, belädt es mit Kitfo und tunkt es in den Dip. Serviere sofort, sobald das Fleisch gemischt ist, und lasse es nicht lange bei Zimmertemperatur stehen.","dauer":0,"tipp":"Traditionell passt dazu milder Frischkäse (Ayib) und Gomen, gekochtes Kohlgemüse."}],"profitipps":["Frischer Metzger, eigenes Brett, kalte Zutaten: Bei rohem Fleisch ist Hygiene das Wichtigste.","Gewürzbutter ist das Herz des Gerichts. Kein Niter Kibbeh zur Hand? Ghee mit etwas Kreuzkümmel ist eine Notlösung.","Pfanne nicht auswischen: Die Reste von Berbere und Butter geben Tiefe.","Nur so viel zubereiten, wie du sofort isst; Reste von rohem Fleisch nicht aufheben."],"varianten":["Durchgegart (Kitfo gebraten): Das Fleisch in der Pfanne mit der Basis garen, bis es nicht mehr rosa ist – die sichere Variante für Risikogruppen.","Leb leb: Das Fleisch nur kurz in der warmen Basis schwenken, bis es außen die Farbe wechselt.","Mit Mitmita (äthiopische Chilimischung) statt Berbere."],"beilagen":["Injera","Ayib (frischer Käse)","Gomen (Kohlgemüse)"],"getraenk":"Tej (Honigwein) oder ein kräftiger Rotwein","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson serviert Kitfo im Red Rooster als warmes Rindertatar und hat das Rezept (mit Gewürzbutter nach der Art vom Volk seiner Frau) im Red-Rooster-Kochbuch veröffentlicht.","quelle":"https://www.foodnetwork.com/fnk/recipes/beef-kitfo-with-awase-9442291"}],"quellen":[{"titel":"Food Network – Beef Kitfo with Awase (Marcus Samuelsson)","url":"https://www.foodnetwork.com/fnk/recipes/beef-kitfo-with-awase-9442291"},{"titel":"First We Feast – The 10 Dishes That Made My Career: Marcus Samuelsson","url":"https://amp.firstwefeast.com/features/marcus-samuelsson-career-changing-dishes"},{"titel":"Wikipedia – Kitfo","url":"https://en.wikipedia.org/wiki/Kitfo"},{"titel":"Tasting Table – Berbere Is Marcus Samuelsson’s Secret Weapon","url":"https://www.tastingtable.com/692769/marcus-samuelsson-berbere-recipe"}],"bild":"teller","farben":["#8b1e12","#c4553a","#e8c9a0"],"schlagworte":["Äthiopien","Festgericht","Tatar","Red Rooster"],"vegetarisch_moeglich":false},{"id":"ostafrika-niter-kibbeh-berbere-butter-samuelsson","name":"Niter Kibbeh und Berbere-Butter nach Art von Marcus Samuelsson","originalname":"ንጥር ቅቤ (Nǝṭǝr qǝbe)","kueche":"ostafrika","region":"Äthiopien / Eritrea","beliebtheit":64,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"sauce","kurz":"Die gewürzte Butter der äthiopischen Küche: Butter wird mit Ingwer, Knoblauch, Zimt und Bockshornklee geklärt und aromatisiert – und mit Berbere zur universellen Würzbutter für Fleisch, Fisch und Gemüse.","hintergrund":"Niter Kibbeh (in Tigrinya „Tesmi“) ist gewürzte, geklärte Butter, die in der äthiopischen und eritreischen Küche für Wot, Kitfo und Shiro gebraucht wird. Man schmilzt Butter, bis sich Milcheiweiß abgesetzt hat, und zieht Gewürze darin gar; danach wird alles abgesiebt. Dadurch ist sie ähnlich wie Ghee hoch erhitzbar, hat aber deutlich mehr Eigengeschmack. Samuelsson hat dieses Rezept in „The Rise“ (2020) veröffentlicht, gemeinsam mit einer Berbere-Butter, und beschreibt sie als geeignet für alles Gepochte oder Gegrillte, zum Beispiel Möhren, Hähnchen und Lamm. Hier eine Heimküchen-Fassung der veröffentlichten Rezeptur, Mengen in metrischen Einheiten.","portionen":12,"zeit":{"vorbereitung":15,"garen":45,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Niter Kibbeh (ergibt etwa 350 ml)","liste":[{"menge":450,"einheit":"g","name":"ungesalzene Butter","hinweis":"gute Qualität, 4 Stücke zu je etwa 113 g"},{"menge":1,"einheit":"Stück","name":"kleine rote Zwiebel","hinweis":"grob gehackt"},{"menge":1,"einheit":"Stück","name":"Ingwerstück, etwa 7,5 cm","hinweis":"geschält, grob gehackt"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"gehackt"},{"menge":1,"einheit":"Stange","name":"Zimtstange"},{"menge":4,"einheit":"Stück","name":"Kardamomkapseln"},{"menge":1,"einheit":"TL","name":"Bockshornkleesamen"},{"menge":1,"einheit":"TL","name":"Kreuzkümmel, gemahlen"},{"menge":1,"einheit":"TL","name":"Oregano, getrocknet"},{"menge":0.5,"einheit":"TL","name":"Kurkuma, gemahlen"},{"menge":4,"einheit":"Zweig","name":"Thymian"}]},{"gruppe":"Für die Berbere-Butter","liste":[{"menge":null,"einheit":"","name":"fertige Niter Kibbeh","hinweis":"geschmolzen"},{"menge":1,"einheit":"EL","name":"Berbere","hinweis":"siehe Rezept in dieser App"}]}],"ausruestung":["mittelgroßer Topf mit dickem Boden","Schaumlöffel","feines Sieb","Käsetuch oder Passiertuch","Schraubglas"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Hacke Zwiebel, Ingwer und Knoblauch und stelle alle Gewürze bereit. Die Stücke sollen grob und gleichmäßig sein, damit sie nicht anbrennen. Schneide die Butter in Würfel, damit sie gleichmäßig schmilzt, und lege Sieb und Käsetuch bereit. Verwende hochwertige Butter ohne Salz; sonst wird die Würzbutter beim Einkochen zu salzig.","dauer":0,"tipp":""},{"titel":"Butter klären","aktion":"schmoren","text":"Schmelze die Butter in einem mittelgroßen Topf bei niedriger Hitze. Sie beginnt zu schäumen; schöpfe den weißen Schaum immer wieder mit einem Löffel ab und lasse die Butter ohne Bräunung weiter garen, bis kein Schaum mehr aufsteigt. Das Fett wird dann klar und goldgelb, am Boden sammelt sich Milcheiweiß. Dieser Schritt entfernt Wasser und Eiweiß und macht die Butter höher erhitzbar.","dauer":15,"tipp":"Hitze niedrig halten: Wird die Butter braun, schmeckt sie nussig-bitter statt rein und sauber."},{"titel":"Gewürze zugeben","aktion":"koecheln","text":"Gib Zwiebel, Ingwer, Knoblauch, Zimtstange, Kardamom, Bockshornklee, Kreuzkümmel, Oregano, Kurkuma und Thymian in die klare Butter. Lasse alles bei kleiner Hitze etwa 15 Minuten ziehen und rühre gelegentlich um. Die Zwiebeln werden leicht gebräunt, die Butter bekommt eine goldene bis orangefarbene Farbe und duftet nach Ingwer, Zimt und Kräutern. Es soll nur sanft blubbern, nie spritzen.","dauer":15,"tipp":""},{"titel":"Ziehen lassen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lass die Butter 30 Minuten ziehen. In dieser Phase geben die Gewürze die letzten Aromen ab, und die Feststoffe sinken ab. Die Butter bleibt dabei flüssig und warm; sie sollte nicht fest werden, bevor du sie siebst. Der Duft verändert sich jetzt von scharf-würzig zu rund und warm, ein Zeichen, dass die Aromen in die Butter übergegangen sind.","dauer":30,"tipp":""},{"titel":"Abseihen","aktion":"abseihen","text":"Lege ein feines Sieb mit einem Käsetuch aus und seihe die Butter langsam in ein sauberes Gefäß. Lass die Gewürze und Feststoffe im Tuch, ohne zu pressen, und gieße vorsichtig, damit das Eiweiß am Topfboden zurückbleibt. Vor dir hast du eine klare, aromatisch duftende goldene Butter. Fülle sie in ein Schraubglas.","dauer":5,"tipp":"Pressen vermeiden: Sonst werden trübe Teilchen in die Butter gedrückt, die später ranzig werden."},{"titel":"Berbere-Butter ansetzen","aktion":"mischen","text":"Für die Berbere-Butter schmilzt du die Niter Kibbeh in einem kleinen Topf bei niedriger bis mittlerer Hitze und rührst einen Esslöffel Berbere ein, bis alles verbunden und tiefrot ist. Die Butter riecht nach Rauch und Wärme. Fülle sie in ein Glas und stelle sie kühl. Beim Erkalten wird sie fest und streichfähig, in der Farbe tief orangerot. Verwende sie zum Beispiel zum Bestreichen von Gemüse oder Fisch kurz vor dem Servieren oder schmelze sie auf frisch gegrilltem Fleisch.","dauer":3,"tipp":""},{"titel":"Lagern und verwenden","aktion":"kuehlen","text":"Lagere beide Würzbutter-Sorten im Kühlschrank in einem luftdichten Glas bis zu drei Wochen. Niter Kibbeh passt zum Braten von Fleisch und Fisch, zum Rühren in Linsen und Bohnen und in Eintöpfe wie Doro Wat, weil sie hoch erhitzbar ist. Die Berbere-Butter eignet sich laut Samuelsson für Gepochtes und Gegrilltes, etwa gegrillte Möhren, geröstetes Hähnchen oder Lamm.","dauer":0,"tipp":"Löffle sie in Eiswürfelformen und friere sie ein, so hast du kleine Portionen zur Hand."}],"profitipps":["Immer ungesalzene Butter verwenden und die Milchfeststoffe konsequent abseihen: Sie verbrennen sonst.","Auf kleinster Flamme arbeiten: Die Butter soll gleichmäßig simmern, nicht braun werden.","Nimm sie statt Öl für Rührei, Linsen oder Bratkartoffeln: ein schneller Weg zu äthiopischem Aroma.","Ghee mit einer Prise Kreuzkümmel und Kurkuma ist ein guter Notbehelf, aber nicht dasselbe."],"varianten":["Gurage-Butter wie bei Samuelssons Kitfo: mit Koriander, Kreuzkümmel, Ajowan und Bockshornklee (siehe Kitfo-Rezept).","Vegane Variante (Yeqimem Zeyet): mit neutralem Pflanzenöl statt Butter.","Mit Rosmarin und Knoblauch für die Shiro-Fassung."],"beilagen":["Doro Wat","Shiro","Tibs","Gegrillte Möhren"],"getraenk":"","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson veröffentlichte Niter Kibbeh und Berbere-Butter in „The Rise“; sie sei für alles Gepochte oder Gegrillte gedacht und vertrage hohe Hitze.","quelle":"https://foodwise.org/recipe/berbere-spice-brown-butter"}],"quellen":[{"titel":"Foodwise – Berbere Spice Brown Butter (Marcus Samuelsson, The Rise)","url":"https://foodwise.org/recipe/berbere-spice-brown-butter"},{"titel":"Food Network – Injera with Tibs (Niter Kibbeh)","url":"https://www.foodnetwork.com/fnk/recipes/injera-with-tibs-9443725"},{"titel":"Wikipedia – Niter kibbeh","url":"https://en.wikipedia.org/wiki/Niter_kibbeh"}],"bild":"dip","farben":["#d89a1c","#f4cf6a","#7a3a12"],"schlagworte":["Gewürzbutter","Äthiopien","Basis"],"vegetarisch_moeglich":true},{"id":"ostafrika-pweza-wa-nazi","name":"Pweza wa Nazi – Oktopus in Kokossauce","originalname":"Pweza wa Nazi","kueche":"ostafrika","region":"Sansibar / Tansania / Küste Kenias","beliebtheit":62,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"meeresfruechte","gang":"hauptgericht","kurz":"Butterweiche Oktopusstücke in duftender Kokos-Curry-Sauce mit Tomaten, Limette und Koriander – ein Küstenklassiker von Sansibar.","hintergrund":"Pweza wa Nazi („Oktopus in Kokos“) gehört zu den typischen Meeresfrüchte-Gerichten der Swahili-Küste, besonders auf Sansibar, wo die Fischer den Oktopus frisch auf den Märkten von Stone Town anbieten. Der Oktopus wird zuerst lange in seinem eigenen Saft weich gegart und dann in einer Sauce aus Zwiebeln, Tomaten, Knoblauch und Currygewürzen mit Kokosmilch geschmort. Die Gewürze verraten den Einfluss indischer und arabischer Händler. Dazu serviert man Reis, Chapati oder Mkate wa kumimina (Reisbrot).","portionen":4,"zeit":{"vorbereitung":25,"garen":90,"ruhen":10},"schwierigkeit":2,"zutaten":[{"gruppe":"Oktopus","liste":[{"menge":1.2,"einheit":"kg","name":"Oktopus","hinweis":"küchenfertig, tiefgekühlt ist ideal (Frieren macht ihn zarter)"},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"halbiert, zum Vorgaren"},{"menge":2,"einheit":"Stück","name":"Lorbeerblätter"},{"menge":100,"einheit":"ml","name":"Wasser"}]},{"gruppe":"Kokossauce","liste":[{"menge":3,"einheit":"EL","name":"Pflanzenöl"},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"fein gehackt"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"gehackt"},{"menge":1,"einheit":"EL","name":"frischer Ingwer","hinweis":"gerieben"},{"menge":3,"einheit":"Stück","name":"reife Tomaten","hinweis":"gewürfelt"},{"menge":1,"einheit":"EL","name":"Currypulver","hinweis":"milder Madras-Curry oder Swahili-Masala"},{"menge":1,"einheit":"TL","name":"Kurkuma"},{"menge":1,"einheit":"TL","name":"Kreuzkümmel","hinweis":"gemahlen"},{"menge":400,"einheit":"ml","name":"Kokosmilch"},{"menge":1,"einheit":"Stück","name":"grüne Chili","hinweis":"ganz"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":"Saft"},{"menge":1,"einheit":"Handvoll","name":"Koriandergrün"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["großer Topf mit Deckel","breiter Schmortopf","scharfes Messer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Taue den Oktopus über Nacht im Kühlschrank auf und spüle ihn gründlich unter kaltem Wasser ab. Entferne, falls noch vorhanden, den Schnabel in der Mitte der Arme und die Augen sowie den Kopfbeutel mit dem Innenleben. Schneide Zwiebeln, Knoblauch und Tomaten klein, reibe den Ingwer und messe die Gewürze ab. So hast du für die Sauce später alles bereit, während der Oktopus gart.","dauer":0,"tipp":""},{"titel":"Oktopus im eigenen Saft vorgaren","aktion":"koecheln","text":"Gib den Oktopus mit der halbierten Zwiebel, den Lorbeerblättern und 100 ml Wasser in einen Topf mit dicht schließendem Deckel. Bringe alles zum Kochen und lass es dann bei kleinster Hitze 50–70 Minuten sanft köcheln. Der Oktopus gibt dabei viel Flüssigkeit ab und gart darin. Er ist fertig, wenn du mit einer Messerspitze ohne Widerstand in den dicksten Arm stichst und die Haut leicht violett glänzt.","dauer":60,"tipp":"Nicht salzen: Der Oktopus bringt selbst genug Salz mit, die Sauce würzt du später ab."},{"titel":"Abkühlen und schneiden","aktion":"schneiden","text":"Nimm den Oktopus aus dem Topf und lass ihn 10 Minuten abkühlen, hebe den Sud auf. Schneide den Oktopus in mundgerechte Stücke von etwa 3 cm; die Arme in Scheiben, den Kopf in Würfel. Die Stücke sind jetzt zart, aber noch bissfest und schmecken leicht nach Meer. Den Sud kannst du später in die Sauce geben, um mehr Geschmack zu erreichen.","dauer":10,"tipp":""},{"titel":"Zwiebeln und Aromaten anbraten","aktion":"anbraten","text":"Erhitze das Öl in einem breiten Topf bei mittlerer Hitze und brate die gehackten Zwiebeln 6–8 Minuten, bis sie weich und goldgelb sind. Füge Knoblauch und Ingwer hinzu und lass sie 1 Minute duften, ohne dass sie braun werden. Der Duft nach frischem Ingwer und süßen Zwiebeln ist die Basis der Sauce. Rühre dabei regelmäßig um, damit nichts am Boden ansetzt und bitter wird.","dauer":8,"tipp":""},{"titel":"Gewürze und Tomaten","aktion":"anbraten","text":"Rühre Currypulver, Kurkuma und Kreuzkümmel ein und röste sie 30 Sekunden unter Rühren, bis sie intensiv duften. Gib die Tomaten dazu und koche sie 8–10 Minuten bei mittlerer Hitze, bis sie zerfallen und das Öl sich am Rand sammelt. Die Masse soll dick und tiefrot-orange sein. Löse den Ansatz mit einem Schuss Oktopus-Sud vom Boden.","dauer":10,"tipp":""},{"titel":"Kokosmilch zugeben","aktion":"koecheln","text":"Gieße die Kokosmilch an und füge etwa 100 ml Oktopus-Sud sowie die ganze Chili hinzu. Bringe alles sanft zum Köcheln und lasse die Sauce 5 Minuten leicht eindicken. Rühre häufig um, damit sich nichts absetzt. Koche die Kokosmilch nicht stark, denn sie kann sonst gerinnen und körnig werden. Die Sauce sollte eine gleichmäßig cremige, leicht orange Farbe haben und nach Kokos und Curry duften.","dauer":5,"tipp":""},{"titel":"Oktopus in der Sauce schmoren","aktion":"schmoren","text":"Gib die Oktopusstücke in die Sauce, rühre vorsichtig um und lass alles bei kleinster Hitze 15–20 Minuten ohne Deckel köcheln, bis die Sauce sämig ist und die Stücke das Aroma aufgenommen haben. Die Sauce soll am Löffel haften und leicht glänzen. Der Oktopus soll weich, aber nicht zerfallend sein, denn er wird bei zu langem Kochen wieder zäh.","dauer":20,"tipp":"Wird die Sauce zu dick, gib einen Schuss Sud nach; ist sie zu dünn, lass sie ohne Deckel weiter einkochen."},{"titel":"Abschmecken","aktion":"abschmecken","text":"Schmecke die Sauce mit Salz, Limettensaft und notfalls einer Prise Chili ab. Die Säure der Limette hebt die Süße der Kokosmilch und bringt Frische. Nimm die Chilischote heraus, falls es nicht zu scharf werden soll. Streue frisch gehacktes Koriandergrün darüber, sodass die Sauce tiefgrün gesprenkelt ist.","dauer":0,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Richte den Oktopus mit viel Sauce in tiefen Tellern an. Serviere dazu duftenden Basmati- oder Kokosreis, frisch gebackene Chapati oder Reisbrot und einen Kachumbari-Salat. Mit den Fingern oder Chapati kannst du die Sauce aufnehmen. Ein paar Limettenspalten am Tellerrand frischen den Geschmack auf. Das Gericht schmeckt am nächsten Tag noch aromatischer und lässt sich sanft aufwärmen.","dauer":0,"tipp":""}],"profitipps":["Tiefgekühlter Oktopus ist meist zarter als frischer, weil das Einfrieren die Fasern aufbricht.","Nie gleich in der Sauce garen: Erst im eigenen Saft vorgaren, dann würzen, so bleibt er saftig und zart.","Kokosmilch nur sanft erhitzen, damit sie nicht gerinnt.","Der Garpunkt: Mit einem Messer in den dicksten Teil stechen – er soll ohne Widerstand weich sein.","Alternativ kann der Oktopus nach dem Vorgaren mit etwas Öl und Limette kurz gegrillt werden, bevor er in die Sauce kommt."],"varianten":["Gegrillter Oktopus mit Pilipili-Marinade","Pweza wa Kukaanga: frittiert und mit Limette serviert","Tintenfisch oder Garnelen statt Oktopus","Kokos-Tomaten-Sauce mit Okra"],"beilagen":["Kokosreis","Chapati","Kachumbari","Mkate wa kumimina"],"getraenk":"Frischer Limettensaft, kühles Bier oder trockener Weißwein","koeche":[],"quellen":[{"titel":"The African Gourmet – Zanzibar octopus stew","url":"https://theafricangourmet.com/2016/04/zanzibar-african-octopus-stew-recipe.html"},{"titel":"Flightlink – The Seafood Dishes You Must Try in Zanzibar","url":"https://blog.flightlink.co.tz/?p=129"}],"bild":"meeresfruechte","farben":["#c4622d","#e8a15a","#f6e2b8"],"schlagworte":["Sansibar","Oktopus","Kokosmilch","Swahili","Meeresfrüchte"],"vegetarisch_moeglich":false,"themen":[]},{"id":"ostafrika-chechebsa","name":"Chechebsa – äthiopisches Fladenbrot-Frühstück","originalname":"ጨጨብሳ","kueche":"ostafrika","region":"Äthiopien","beliebtheit":52,"hauptkategorie":"vegetarisch","kurz":"Zerrissene Fladenbrotstücke, in würziger Butter (Niter Kibbeh) und Berbere gebraten, serviert mit Honig oder Joghurt.","hintergrund":"Chechebsa, auch Kita Firfir genannt, ist ein beliebtes äthiopisches Frühstück aus ungesäuertem Fladenbrot, das zerrissen und in Gewürzbutter und Berbere geschwenkt wird. Es wird mit Honig oder Joghurt gegessen und oft zum Fastenbrechen oder an Feiertagen serviert. Die Grundlage ist Niter Kibbeh, eine geklärte Butter mit Gewürzen, die in der äthiopischen Küche zahlreiche Gerichte aromatisiert. Chechebsa wird traditionell mit den Fingern aus einer gemeinsamen Schale gegessen.","portionen":4,"zeit":{"vorbereitung":30,"garen":40,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Niter Kibbeh (Gewürzbutter)","liste":[{"menge":250,"einheit":"g","name":"Butter","hinweis":""},{"menge":1,"einheit":"Stück","name":"kleine Zwiebel","hinweis":"grob gehackt"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"geschält"},{"menge":1,"einheit":"Stück","name":"Ingwer, daumengroß","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":0.25,"einheit":"TL","name":"Bockshornkleesamen","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange, klein","hinweis":""},{"menge":2,"einheit":"Stück","name":"Kardamomkapseln","hinweis":""},{"menge":2,"einheit":"Stück","name":"Nelken","hinweis":""}]},{"gruppe":"Fladen","liste":[{"menge":300,"einheit":"g","name":"Weizenmehl Type 550","hinweis":"ersatzweise halb Teffmehl"},{"menge":1,"einheit":"TL","name":"Backpulver","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":200,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":1,"einheit":"EL","name":"Niter Kibbeh","hinweis":"oder Öl"}]},{"gruppe":"Zum Braten und Servieren","liste":[{"menge":4,"einheit":"EL","name":"Niter Kibbeh","hinweis":""},{"menge":1.5,"einheit":"EL","name":"Berbere-Gewürzmischung","hinweis":"im Afro-Laden oder online"},{"menge":100,"einheit":"g","name":"Naturjoghurt","hinweis":""},{"menge":2,"einheit":"EL","name":"Honig","hinweis":""}]}],"ausruestung":["Topf mit schwerem Boden","Feinsieb und Mulltuch","beschichtete Pfanne","Teigroller"],"schritte":[{"titel":"Niter Kibbeh kochen","aktion":"kochen","text":"Schmelze die Butter in einem schweren Topf bei niedriger Hitze und gib Zwiebel, Knoblauch, Ingwer, Kurkuma, Bockshornklee, Zimt, Kardamom und Nelken dazu. Lasse alles 30–40 Minuten sanft köcheln, ohne dass es kräftig blubbert oder bräunt: Die Butter soll nur leise brutzeln. Dabei verdampft das Wasser, die Milchbestandteile setzen sich ab und die Butter wird klar, goldgelb und duftet nach Gewürzen. Seihe sie durch ein Sieb mit Tuch in ein Glas und lasse sie abkühlen.","dauer":35,"tipp":"Niter Kibbeh hält sich im Kühlschrank mehrere Wochen und ist die Basis vieler äthiopischer Gerichte."},{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Mehl, Backpulver und Salz ab, stelle das Wasser bereit und lege Berbere, Joghurt und Honig für später daneben. Du brauchst eine große, beschichtete Pfanne, einen Teigroller und einen großen Teller zum Stapeln der Fladen. Hole das Niter Kibbeh heraus und prüfe, dass es flüssig oder weich genug zum Verarbeiten ist; kühl gelagert ist es fest und muss kurz erwärmt werden. Plane, dass Fladen und Würzbutter erst kurz vor dem Servieren zusammenkommen.","dauer":0,"tipp":""},{"titel":"Teig kneten","aktion":"kneten","text":"Vermische Mehl, Backpulver und Salz in einer Schüssel. Gib 1 EL Niter Kibbeh und das Wasser dazu und knete alles 5 Minuten, bis ein fester, glatter Teig entsteht, der nicht mehr klebt. Wickle ihn in Folie oder decke ihn mit einem Tuch ab und lasse ihn 20 Minuten ruhen. In dieser Zeit entspannt sich das Gluten, und der Teig lässt sich später dünn ausrollen, ohne zurückzuschnappen. Er sollte sich weich wie ein Ohrläppchen anfühlen.","dauer":20,"tipp":""},{"titel":"Fladen ausrollen","aktion":"ausrollen","text":"Teile den Teig in 4 gleich große Stücke und forme sie zu Kugeln. Rolle jede Kugel auf einer leicht bemehlten Fläche zu einem runden Fladen von etwa 20 cm Durchmesser und 2 mm Dicke aus. Drehe den Teig zwischen den Rollbewegungen, damit der Fladen gleichmäßig rund wird. Je dünner der Fladen, desto knuspriger und schneller gar wird er. Lege die ausgerollten Fladen auf Backpapier und bestäube sie leicht mit Mehl, damit sie nicht zusammenkleben.","dauer":0,"tipp":""},{"titel":"Fladen backen","aktion":"braten","text":"Erhitze eine beschichtete Pfanne ohne Fett bei mittlerer Hitze. Backe jeden Fladen 2–3 Minuten pro Seite, bis er goldbraun gefleckt ist und sich an einigen Stellen leicht aufbläht. Der Fladen soll fest und trocken sein, nicht zäh oder blass. Er duftet dann nach geröstetem Mehl. Stapele die fertigen Fladen und decke sie mit einem Tuch ab, damit sie nicht austrocknen.","dauer":10,"tipp":"Zu hohe Hitze lässt die Fladen außen verbrennen, bevor sie innen gar sind."},{"titel":"Fladen zerreißen","aktion":"schneiden","text":"Reiße die abgekühlten Fladen mit den Händen in unregelmäßige, etwa 3 cm große Stücke. Verzichte bewusst auf ein Messer: Die rauen, ausgefransten Ränder nehmen später die Butter besser auf. Gib die Stücke in eine große Schüssel. Wenn du die Fladen schon am Vortag gebacken hast, sind sie trockener und saugen noch mehr Gewürzbutter, was äthiopische Köche oft bevorzugen.","dauer":0,"tipp":""},{"titel":"Berbere-Butter und Brot schwenken","aktion":"anbraten","text":"Erwärme 4 EL Niter Kibbeh in einer großen Pfanne bei mittlerer Hitze, bis sie flüssig ist und duftet. Rühre den Berbere ein und lasse ihn 30–60 Sekunden köcheln: Die Butter färbt sich tiefrot, es entsteht ein würziger, leicht rauchiger Duft. Gib sofort die Fladenstücke dazu und schwenke sie 2–3 Minuten, bis jedes Stück rot, glänzend und gleichmäßig durchtränkt ist. Probiere ein Stück: Es soll würzig, butterig und angenehm scharf sein.","dauer":5,"tipp":"Berbere verbrennt schnell und wird dann bitter: Hitze reduzieren und die Brotstücke zügig zugeben."},{"titel":"Anrichten und essen","aktion":"anrichten","text":"Schütte das heiße Chechebsa in eine große Schale oder auf einen Teller. Gib Joghurt und Honig in kleine Schälchen dazu. In Äthiopien isst man gemeinsam aus einer Schale mit den Fingern, wobei man die Brotstücke erst mit Joghurt, dann mit Honig kombiniert: scharf, cremig und süß in einem Bissen. Dazu passt äthiopischer Kaffee. Das Gericht schmeckt am besten frisch und heiß, denn abgekühlt wird die Butter fest und das Brot trocken.","dauer":0,"tipp":""}],"profitipps":["Niter Kibbeh auf Vorrat herstellen.","Fladen dünn ausrollen.","Berbere nicht verbrennen.","Mit Honig oder Joghurt servieren.","Teffmehl macht den Fladen authentischer."],"varianten":["Mit Spiegelei","Mit Zwiebeln und Tomaten","Süß mit Honig","Mit Teffmehl","Mit scharfer Berbere-Sauce"],"beilagen":["Joghurt","Honig","Äthiopischer Kaffee","Spiegelei"],"getraenk":"Äthiopischer Kaffee (Buna) oder Tee.","quellen":[{"titel":"Fit-fit (Wikipedia)","url":"https://en.wikipedia.org/wiki/Fit-fit"},{"titel":"Chechebsa, Ethiopian torn flatbread (Tara's Multicultural Table)","url":"https://tarasmulticulturaltable.com/chechebsa-ethiopian-torn-flatbread/"},{"titel":"Berbere Spice Brown Butter (Foodwise)","url":"https://foodwise.org/recipe/berbere-spice-brown-butter"}],"bild":"brot","farben":["#a33a1c","#e0a14a","#f2e2c0"],"schlagworte":["Äthiopien","Berbere","Niter Kibbeh","Fladenbrot"],"vegetarisch_moeglich":true,"gang":"fruehstueck","fleischsorte":"","koeche":[]},{"id":"ostafrika-berbere-moehren-fenchel-orangen-samuelsson","name":"Berbere-Möhren und Fenchel mit Orangen nach Art von Marcus Samuelsson","originalname":"","kueche":"ostafrika","region":"Äthiopien trifft USA","beliebtheit":50,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"beilage","kurz":"Gebratene Möhren und Fenchel in Orangensaft, Butter und äthiopischer Würzmischung – süß, würzig, frisch von Minze und Orangenfilets.","hintergrund":"Samuelsson zeigt in „Marcus Off Duty“ (2014), wie man vertraute Gemüse mit Berbere neu würzt: Die Mischung macht Möhren und Fenchel erdiger und die Orangen bringen Frische. Er betont, dass Berbere kein feuriges Gemisch ist: Lange mitgegart schmeckt es erdig, am Ende zugegeben lebendig. Das Rezept ist eine einfache Beilage mit Butter, die sich gut zu Hähnchen, Lamm, Fisch oder Linsengerichten eignet. Dies ist eine Heimküchen-Fassung der veröffentlichten Rezeptur, Mengen in metrischen Einheiten; die Quelle nennt vier Fenchelknollen, was ungewöhnlich viel im Verhältnis zu den Möhren ist, deshalb sind es hier zwei große.","portionen":4,"zeit":{"vorbereitung":20,"garen":20,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Gemüse","liste":[{"menge":2,"einheit":"EL","name":"Olivenöl"},{"menge":60,"einheit":"g","name":"Butter","hinweis":"in zwei Portionen"},{"menge":2,"einheit":"Stück","name":"große Fenchelknollen","hinweis":"Strunk entfernt, quer in 1,5-cm-Scheiben; die Quelle nennt 4 Knollen"},{"menge":450,"einheit":"g","name":"Möhren","hinweis":"geschält, in 2,5-cm-Stücke"},{"menge":0.5,"einheit":"TL","name":"Salz"},{"menge":0.25,"einheit":"TL","name":"schwarzer Pfeffer"},{"menge":2,"einheit":"Stück","name":"Orangen, Saft","hinweis":"für den Saft"},{"menge":2,"einheit":"Stück","name":"Orangen","hinweis":"filetiert, zum Servieren"},{"menge":1,"einheit":"TL","name":"Berbere","hinweis":"plus mehr zum Bestreuen"},{"menge":15,"einheit":"g","name":"Minzblätter","hinweis":"gezupft"}]}],"ausruestung":["große Pfanne","scharfes Messer zum Filetieren","Backblech mit Backpapier (für die Ofenvariante)"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wasche und schäle die Möhren und schneide sie in 2,5 cm lange Stücke. Dicke Enden halbierst du, damit alles gleich schnell gar wird. Fenchelknollen halbierst du, entfernst den harten Strunk und schneidest sie quer in etwa 1,5 cm dicke Scheiben; das zarte grüne Kraut hebst du auf. Die Orangen presst du zur Hälfte aus und filetierst die übrigen, indem du Schale samt weißer Haut wegschneidest und die Segmente zwischen den Trennhäuten herauslöst. Zupfe die Minze.","dauer":0,"tipp":""},{"titel":"Gemüse anbraten","aktion":"anbraten","text":"Erhitze Olivenöl und die Hälfte der Butter in einer großen Pfanne bei mittlerer bis hoher Hitze. Gib Fenchel und Möhren hinein, würze mit Salz und Pfeffer und wende sie, bis sie rundum mit Fett überzogen sind. Das Gemüse soll leise brutzeln; es riecht jetzt nach süßer Butter. Nicht zu eng legen, damit es Farbe nimmt und nicht dämpft.","dauer":3,"tipp":""},{"titel":"Bräunen","aktion":"anbraten","text":"Gib die restliche Butter dazu und brate etwa fünf Minuten weiter, bis das Gemüse weicher wird und an den Kanten bräunt. Die Fenchelscheiben nehmen schneller Farbe an als die Möhren; wende sie vorsichtig. Das Gemüse sollte außen goldbraun sein und innen noch Biss haben. Die Butter schäumt und duftet nussig; lass sie nicht dunkelbraun werden, sonst schmeckt sie bitter und überdeckt die feine Würze des Berbere. Stelle bei Bedarf die Hitze etwas niedriger.","dauer":5,"tipp":"Karotten sind nach etwa zehn Minuten gar; piekse eine mit einer Messerspitze an."},{"titel":"Mit Orangensaft und Berbere ablöschen","aktion":"reduzieren","text":"Gieße den Orangensaft in die Pfanne, streue einen Teelöffel Berbere darüber und wende alles, damit das Gemüse die Würze aufnimmt. Der Saft verdampft und bildet eine glänzende, leicht klebrige Glasur. Reduziere die Hitze auf niedrige Stufe, wenn der Saft zu schnell einkocht. Das Gemüse darf noch leichten Biss behalten.","dauer":4,"tipp":""},{"titel":"Orangenfilets und Minze unterheben","aktion":"mischen","text":"Hebe Orangensegmente und Minze behutsam unter, damit die Filets nicht zerfallen. Die Minze soll nur kurz mitwärmen, damit sie ihr Aroma behält und nicht dunkel wird. Der Duft nach Orange, Butter und Gewürz steigt auf; probiere ein Stück und salze bei Bedarf nach. Wirkt das Gemüse zu süß, hilft ein Spritzer Zitronensaft, wirkt es zu flach, noch eine Prise Berbere. Die Pfanne bleibt dabei nur noch kurz auf der Herdplatte.","dauer":1,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Fülle das Gemüse in eine vorgewärmte Schüssel und bestäube es mit etwas zusätzlichem Berbere und Minzblättern. Das Fenchelgrün darfst du darüber streuen, es bringt einen zarten Anisduft und frische Farbe. Serviere die Beilage warm oder lauwarm, nicht heiß, damit die Minze nicht welkt und der Orangenduft erhalten bleibt. Es schmeckt warm zu gebratenem Fisch, Lammkoteletts und Hähnchen und eignet sich auch gut als Beilage zu Linsen- und Kichererbsengerichten.","dauer":0,"tipp":"Ofenvariante: Mit Öl, Berbere, Salz und Pfeffer auf einem Blech bei 200 °C Ober-/Unterhitze (180 °C Umluft) 25 bis 30 Minuten rösten, einmal wenden; Orangensaft, Filets und Minze erst vor dem Servieren unterheben."}],"profitipps":["Berbere hat zwei Gesichter: Mitgegart erdig, kurz vor dem Servieren frisch und lebendig.","Butter in zwei Portionen: erst zum Anbraten, dann zum Verfeinern.","Die Orangenfilets erst ganz am Ende zugeben, damit sie ihre Form behalten.","Ofenvariante spart Aufmerksamkeit und gibt mehr Röstaroma."],"varianten":["Aus dem Ofen: bei 200 °C rösten und Saft und Minze am Ende zugeben.","Mit Pastinaken oder Süßkartoffeln statt Möhren.","Mit Grapefruit statt Orange für mehr Säure."],"beilagen":["Gebratenes Hähnchen","Lamm","Linsen"],"getraenk":"Weißwein mit etwas Restsüße oder Orangensaftschorle","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson hat die Möhren-Fenchel-Beilage in „Marcus Off Duty“ veröffentlicht und betont, dass Berbere nicht feurig ist: Lang gegart wird es erdig, zum Schluss belebend.","quelle":"https://www.foodnetwork.com/fnk/recipes/berbere-roasted-carrots-and-fennel-with-oranges-9440809"}],"quellen":[{"titel":"Food Network – Berbere Roasted Carrots & Fennel with Oranges (Marcus Samuelsson)","url":"https://www.foodnetwork.com/fnk/recipes/berbere-roasted-carrots-and-fennel-with-oranges-9440809"},{"titel":"Tasting Table – Berbere Is Marcus Samuelsson’s Secret Weapon","url":"https://www.tastingtable.com/692769/marcus-samuelsson-berbere-recipe"}],"bild":"salat","farben":["#d9731a","#f0a948","#6b8f3a"],"schlagworte":["Beilage","Berbere","Gemüse"],"vegetarisch_moeglich":true}]);
